def _set_line_money(item: dict, column: str, text: str) -> dict:
    """A price typed into a line's Unit $ or Line $ cell.

    Unit $ is the price each; Line $ is the line's total, and sets the price
    each from it (to four places, so 100.00 over 3 stays 100.00). Either way
    the price is then the line's own, set by hand. Empty goes back to the
    customer's tier price. Raises ValueError for anything not a price.
    """
    text = str(text or "").replace("✎", "").strip().lstrip("$").replace(",", "")
    if not text:
        item.pop("Unit Price", None)
        item.pop("Price Source", None)
        return item
    value = float(text)
    if value < 0:
        raise ValueError("A price cannot be less than nothing.")
    if column == "total":
        qty = _pricing.line_quantity(item)
        if qty <= 0:
            raise ValueError("The line has no quantity to share the total over.")
        value = value / qty
    item["Unit Price"] = round(value, 4)
    item["Price Source"] = "manual"
    return item


def _inline_money_edit(tree, iid, column, initial, on_value):
    """Type over one cell of a table: Enter (or clicking away) keeps it,
    Escape leaves it as it was. `on_value(text)` gets what was typed."""
    try:
        x, y, w, h = tree.bbox(iid, column)
    except (ValueError, tk.TclError):
        return None
    var = tk.StringVar(value=str(initial or "").replace("✎", "").strip()
                       .replace("—", ""))
    ent = tk.Entry(tree, textvariable=var, justify="right", font=F_BODY,
                   relief="flat", bd=0, highlightthickness=1,
                   highlightbackground=CA, highlightcolor=CA)
    ent.place(x=x, y=y, width=max(w, px(70)), height=h)
    ent.focus_set()
    ent.select_range(0, "end")
    state = {"done": False}

    def _finish(keep):
        if state["done"]:
            return
        state["done"] = True
        text = var.get()
        try:
            ent.destroy()
        except tk.TclError:
            pass
        if keep:
            on_value(text)

    ent.bind("<Return>", lambda _e: _finish(True))
    ent.bind("<KP_Enter>", lambda _e: _finish(True))
    ent.bind("<Escape>", lambda _e: _finish(False))
    ent.bind("<FocusOut>", lambda _e: _finish(True))
    ent.commit = lambda: _finish(True)          # what Enter does
    return ent


def _fee_value(text: str):
    """A delivery fee as typed: a number, or None for "no fee". Anything
    that is not a number is no fee rather than an error mid-save."""
    text = str(text or "").strip().lstrip("$").replace(",", "")
    try:
        fee = round(float(text), 2) if text else None
    except ValueError:
        return None
    return fee if fee and fee > 0 else None


def _line_money(item: dict) -> tuple:
    """("27.50", "275.00") for a priced line - a hand-set price marked with
    a pencil - or ("—", "—")."""
    try:
        unit = float(item.get("Unit Price") or 0)
    except (TypeError, ValueError):
        unit = 0.0
    if unit <= 0:
        return ("—", "—")
    qty = _pricing.line_quantity(item)
    mark = "✎ " if item.get("Price Source") == "manual" else ""
    return (f"{mark}{_pricing.money_text(unit)}", f"{unit * qty:,.2f}")


def _order_money(items) -> tuple:
    """(total ex GST of the priced lines, how many lines have no price)."""
    total, missing = 0.0, 0
    for it in items or []:
        try:
            unit = float(it.get("Unit Price") or 0)
        except (TypeError, ValueError):
            unit = 0.0
        if unit > 0:
            total += unit * _pricing.line_quantity(it)
        else:
            missing += 1
    return (round(total, 2), missing)


def _tier_price_text(row: dict) -> str:
    """"27.00" - or "27.00 / 25.00 / 23.00" once Tier 2 or 3 is set, with a
    tier left blank showing Tier 1's price in brackets."""
    t1 = float(row.get("unit_price") or 0)
    tiers = [row.get("unit_price_2"), row.get("unit_price_3")]
    if all(t in (None, "") for t in tiers):
        return f"{t1:,.2f}"
    return " / ".join([f"{t1:,.2f}"] + [
        f"({t1:,.2f})" if t in (None, "") else f"{float(t):,.2f}" for t in tiers])


def _price_cost_cells(row: dict) -> tuple:
    """The Cost and Margin cells for one product.

    A product nobody has costed shows a dash in both, not a zero and not a
    100% margin. Reading "100%" off a row that simply has no cost against it
    is how a price list ends up trusted for a decision it cannot support.
    """
    try:
        price = float(row.get("unit_price") or 0)
        cost = float(row.get("unit_cost") or 0)
    except (TypeError, ValueError):
        return ("—", "—")
    if cost <= 0:
        return ("—", "—")
    if price <= 0:
        return (f"{cost:,.2f}", "—")
    return (f"{cost:,.2f}", f"{(price - cost) / price * 100:.0f}%")


def _items_cell(row: dict) -> str:
    """The # Items column: how many lines, and how many are made.

    A bare count never said whether anything had been started. "3/8" does,
    and it costs the list nothing — the database counts them alongside the
    total.
    """
    return _db.progress_cell(row.get("n_items"), row.get("n_made"))


def due_bucket(row: dict, today=None) -> str:
    """Where an order sits against its due date.

    One of "overdue", "today", "week" (the next seven days), "later",
    "none" (no date given) or "done". "ASAP" with no date counts as due today
    — it is the one wording that means "now" rather than "sometime".
    """
    if (row.get("status") or "Pending") in DONE_STATUSES:
        return "done"
    raw = (row.get("date_due") or "").strip()
    if not raw:
        return "none"
    if raw.lower() == "asap":
        return "today"
    parsed = parse_date(raw)
    if not parsed:
        return "none"
    today = today or datetime.date.today()
    days = (parsed.date() - today).days
    if days < 0:
        return "overdue"
    if days == 0:
        return "today"
    if days <= 7:
        return "week"
    return "later"


def due_sort_key(row: dict):
    """Sort orders by when they are due, soonest first, undated last."""
    raw = (row.get("date_due") or "").strip()
    if raw.lower() == "asap":
        return (0, datetime.date.min)
    parsed = parse_date(raw)
    if not parsed:
        return (1, datetime.date.max)      # undated sinks to the bottom
    return (0, parsed.date())


class _Tooltip:
    """A small label that appears under a widget on hover.

    For controls whose name has to be short enough to fit but is too short to
    explain itself.
    """

    def __init__(self, widget, text: str, delay: int = 450):
        self._widget = widget
        self._text = text
        self._delay = delay
        self._after = None
        self._window = None
        widget.bind("<Enter>", self._schedule, add="+")
        widget.bind("<Leave>", self._hide, add="+")
        widget.bind("<ButtonPress>", self._hide, add="+")

    def _schedule(self, _event=None):
        self._cancel()
        self._after = self._widget.after(self._delay, self._show)

    def _cancel(self):
        if self._after is not None:
            try:
                self._widget.after_cancel(self._after)
            except Exception:
                pass
            self._after = None

    def _show(self):
        if self._window is not None:
            return
        try:
            x = self._widget.winfo_rootx()
            y = self._widget.winfo_rooty() + self._widget.winfo_height() + 4
        except Exception:
            return
        self._window = tk.Toplevel(self._widget)
        self._window.wm_overrideredirect(True)
        self._window.configure(bg=CTX)
        tk.Label(self._window, text=self._text, bg=CTX, fg="white",
                 font=F_SM, justify="left", wraplength=260,
                 padx=8, pady=5).pack()
        self._window.wm_geometry(f"+{x}+{y}")

    def _hide(self, _event=None):
        self._cancel()
        if self._window is not None:
            try:
                self._window.destroy()
            except Exception:
                pass
            self._window = None


def _pick_one(parent, title: str, prompt: str, options: list,
              current: str = "") -> str:
    """A small "which of these?" dialog. Returns "" if it was closed."""
    dlg = tk.Toplevel(parent)
    dlg.title(title)
    dlg.configure(bg=CBG)
    dlg.transient(parent)
    dlg.grab_set()
    dlg.resizable(False, False)
    tk.Label(dlg, text=title, bg=CA, fg="white", font=F_BOLD,
             padx=16, pady=10, anchor="w").pack(fill="x")
    body = tk.Frame(dlg, bg=CBG, padx=16, pady=14)
    body.pack(fill="both", expand=True)
    tk.Label(body, text=prompt, bg=CBG, fg=CTX, font=F_BODY,
             anchor="w", justify="left").pack(anchor="w", pady=(0, 10))
    var = tk.StringVar(value=current or (options[0] if options else ""))
    for opt in options:
        tk.Radiobutton(body, text=opt, variable=var, value=opt,
                       bg=CBG, fg=CTX, font=F_BODY, activebackground=CBG,
                       activeforeground=CTX, selectcolor=CCA, anchor="w",
                       highlightthickness=0, bd=0).pack(anchor="w")
    chosen = {"value": ""}

    def _ok():
        chosen["value"] = var.get()
        dlg.destroy()

    foot = tk.Frame(dlg, bg=CBG, padx=16, pady=10)
    foot.pack(fill="x")
    flat_btn(foot, "Cancel", dlg.destroy, bg=CNE,
             pady=7).pack(side="right", padx=(8, 0))
    flat_btn(foot, "OK", _ok, bg=CGR, pady=7).pack(side="right")
    dlg.bind("<Escape>", lambda _e: dlg.destroy())
    dlg.bind("<Return>", lambda _e: _ok())
    dlg.update_idletasks()
    dlg.geometry(f"+{parent.winfo_rootx() + 160}+{parent.winfo_rooty() + 140}")
    parent.wait_window(dlg)
    return chosen["value"]


def apply_stepped_filter_note(item: dict) -> dict:
    """Ensure stepped-filter items carry the *STEPPED FILTER* customer note.

    Mutates and returns ``item``. The note is prepended to any existing notes
    and is idempotent (never added twice).
    """
    if (item.get("Filter Type") or "").strip() != "Stepped Filter":
        return item
    notes = (item.get("Notes") or "").strip()
    if STEPPED_FILTER_NOTE.lower() not in notes.lower():
        item["Notes"] = f"{STEPPED_FILTER_NOTE}\n{notes}".strip() if notes else STEPPED_FILTER_NOTE
    return item


def _load_settings() -> dict:
    if SETTINGS_FILE.exists():
        try:
            return json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
        except Exception:
            pass
    return {"custom_media_types": [], "supabase_anon_key": ""}


def _save_settings(data: dict) -> None:
    SETTINGS_FILE.write_text(json.dumps(data, indent=2), encoding="utf-8")

