# Packing, the filter calculator, delivery labels, and merging customers
# ═══════════════════════════════════════════════════════════════════════════

def _who_now() -> str:
    try:
        return (_db.current_full_name() or _db.current_username() or "") \
            if _db.is_ready() else ""
    except Exception:
        return ""


def _line_size(item: dict) -> str:
    w, h, d = _order_packing.line_dims(item)
    parts = [str(p) for p in (w, h, d) if p not in (None, "", 0)]
    return " × ".join(parts) if parts else "—"


def make_delivery_labels(order: dict, items: list, settings=None,
                         customer=None, only_wrap_ids=None,
                         lookup_customer=True):
    """The delivery labels PDF for one order, with no windows.

    Returns (path, problems): the PDF's path, or None with the reasons it
    could not be made. Safe off the main thread, which is how Generate Output
    makes them alongside the worksheets. The base address is read once, here,
    for the whole request.
    """
    header = dict(order.get("header") or {})
    if settings is None:
        try:
            settings = _calc_settings.load(force=True)
        except Exception:
            settings = _calc_settings.cached()
    base = _calc_settings.base_address(settings)
    if customer is None and lookup_customer and _db.is_ready():
        try:
            customer = _db.customer_for_order(
                order.get("customer_name") or header.get("Customer Name", ""),
                order.get("customer_id") or "")
        except Exception:
            customer = None
    record = {"order_number": order.get("order_number")
              or header.get("Order Number", ""),
              "customer_name": order.get("customer_name")
              or header.get("Customer Name", ""),
              "header": header, "items": items}
    try:
        labels = _delivery_labels.build_for_order(record, customer, settings,
                                                  base,
                                                  only_wrap_ids=only_wrap_ids)
    except _delivery_labels.LabelError as exc:
        problems = list(exc.problems)
        if not customer:
            problems.append("No customer account matches this order's "
                            "customer name, so there is no delivery address. "
                            "Link it to a customer first.")
        return None, problems
    if not labels:
        # Nothing but bag filters: they get no labels, and that is not a
        # problem to report.
        return None, []
    safe = re.sub(r"[^A-Za-z0-9_-]+", "_",
                  str(record["order_number"] or "order")).strip("_") or "order"
    ORDERS_DIR.mkdir(parents=True, exist_ok=True)
    stamp = _dt_module.datetime.now().strftime("%Y%m%d-%H%M%S")
    path = ORDERS_DIR / f"delivery_labels_{safe}_{stamp}.pdf"
    try:
        _delivery_labels.render_pdf(labels, str(path))
    except Exception as exc:
        return None, [f"Could not make the labels: {exc}"]
    try:
        _db.log_action("delivery_labels_printed",
                       f"O/N: {record['order_number']} | "
                       f"{len(labels)} label{'s' if len(labels) != 1 else ''}")
    except Exception:
        pass
    return str(path), []


def print_delivery_labels(parent, order: dict, items: list,
                          only_wrap_ids=None, settings=None) -> "str | None":
    """Make the delivery labels for one saved order and open them.

    Returns the PDF's path, or None after telling the person why it could
    not be made.
    """
    path, problems = make_delivery_labels(order, items, settings,
                                          only_wrap_ids=only_wrap_ids)
    if not path and not problems:
        messagebox.showinfo("Delivery labels",
                            "Nothing to label: bag filters get no delivery "
                            "labels.", parent=parent)
        return None
    if not path:
        fix = "\n".join(f"  • {p}" for p in problems[:12])
        messagebox.showwarning(
            "Delivery labels",
            "These labels can't be printed yet:\n\n" + fix +
            "\n\nAddress problems are fixed on the customer's account; "
            "packing problems under Packing and weights.",
            parent=parent)
        return None
    _open_path(path)
    return path


class PackingDialog(tk.Toplevel):
    """How each line of an order is wrapped, what each wrap weighs, and its
    delivery labels.

    The office sets a line's plan here - automatic, or exactly as the
    customer asked - and it is saved on the order, so the floor sees the
    same thing on the worksheet and the labels match. Nothing over 10 kg or
    over a handling limit is let through quietly: a conflict is shown with a
    suggested plan next to it, and the choice stays with the person.
    """

    def __init__(self, master, row: dict, header: dict, items: list,
                 on_saved=None):
        super().__init__(master)
        self.title(f"Packing and weights — {row.get('order_no') or ''}")
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.row, self.header = row, dict(header or {})
        self.items = _db.with_line_ids([dict(i) for i in items or []])
        self.on_saved = on_saved
        self.settings = _calc_settings.cached()
        self.order_id = row.get("db_id") if row.get("source") == "db" else None
        _centre_on_parent(self, master, px(1040), px(700))
        self.bind("<Escape>", lambda _e: self.destroy())

        top = tk.Frame(self, bg=CA, padx=px(16), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text="Packing and weights", bg=CA, fg="white",
                 font=(FAM, 13, "bold")).pack(anchor="w")
        tk.Label(top, text="Up to 10 kg a wrap, wrapping included. A plan the "
                           "office sets is kept exactly as set.",
                 bg=CA, fg="white", font=F_SM).pack(anchor="w")

        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Close", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        flat_btn(foot, "Print all delivery labels", self._print_all, bg=CA,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))
        flat_btn(foot, "Reprint selected wraps", self._print_selected,
                 bg=CNE, pady=px(6)).pack(side="right", padx=(0, px(8)))
        self.status = tk.StringVar(value="")
        tk.Label(foot, textvariable=self.status, bg=CBG, fg=CMU,
                 font=F_SM).pack(side="left")

        body = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        body.pack(fill="both", expand=True)

        cols = ("line", "size", "qty", "plan", "wraps", "status", "brace")
        self.lines = ttk.Treeview(body, columns=cols, show="headings",
                                  height=6, style="TAF.Treeview",
                                  selectmode="browse")
        for col, (txt, wd) in {"line": ("Line", 50), "size": ("Size", 150),
                               "qty": ("Qty", 50), "plan": ("Plan", 280),
                               "wraps": ("Wraps", 60),
                               "status": ("Status", 170),
                               "brace": ("Bracing", 170)}.items():
            self.lines.heading(col, text=txt, anchor="w")
            self.lines.column(col, width=px(wd), anchor="w",
                              stretch=col in ("plan", "status"))
        self.lines.tag_configure("problem", foreground=CRD)
        self.lines.pack(fill="x")
        self.lines.bind("<<TreeviewSelect>>", lambda _e: self._show_line())

        mid = tk.Frame(body, bg=CCA, highlightbackground=CBR,
                       highlightthickness=1, padx=px(12), pady=px(10))
        mid.pack(fill="x", pady=(px(10), 0))
        self.mode = tk.StringVar(value="automatic")
        r1 = tk.Frame(mid, bg=CCA)
        r1.pack(fill="x")
        tk.Label(r1, text="Packing:", bg=CCA, fg=CTX, font=F_BOLD
                 ).pack(side="left")
        for val, txt in (("automatic", "Automatic"),
                         ("manual", "Manual (as the customer asked)")):
            tk.Radiobutton(r1, text=txt, value=val, variable=self.mode,
                           bg=CCA, fg=CTX, font=F_BODY, activebackground=CCA,
                           selectcolor=CBG).pack(side="left", padx=(px(8), 0))
        self.awkward = tk.BooleanVar(value=False)
        tk.Checkbutton(r1, text="Awkward to handle", variable=self.awkward,
                       bg=CCA, fg=CTX, font=F_BODY, activebackground=CCA,
                       selectcolor=CBG).pack(side="right")

        r2 = tk.Frame(mid, bg=CCA)
        r2.pack(fill="x", pady=(px(8), 0))
        self.per_wrap = tk.StringVar()
        self.n_wraps = tk.StringVar()
        self.explicit = tk.StringVar()
        self.areas = tk.StringVar()
        for label, var, width in (("Filters per wrap", self.per_wrap, 6),
                                  ("Number of wraps", self.n_wraps, 6),
                                  ("Or each wrap (e.g. 5, 5, 2)",
                                   self.explicit, 16)):
            tk.Label(r2, text=label, bg=CCA, fg=CMU, font=F_SM
                     ).pack(side="left", padx=(0, px(4)))
            field_entry(r2, textvariable=var, width=width
                        ).pack(side="left", padx=(0, px(14)))
        r3 = tk.Frame(mid, bg=CCA)
        r3.pack(fill="x", pady=(px(6), 0))
        tk.Label(r3, text="Customer areas (e.g. Area A = 10; Area B = 10)",
                 bg=CCA, fg=CMU, font=F_SM).pack(side="left", padx=(0, px(4)))
        field_entry(r3, textvariable=self.areas, width=40
                    ).pack(side="left", fill="x", expand=True)
        r4 = tk.Frame(mid, bg=CCA)
        r4.pack(fill="x", pady=(px(8), 0))
        flat_btn(r4, "Save packing for this line", self._save_line, bg=CGR,
                 pady=px(5)).pack(side="left")
        flat_btn(r4, "Use the suggested plan", self._use_proposal,
                 bg=CNE, pady=px(5)).pack(side="left", padx=(px(8), 0))
        flat_btn(r4, "Weight calculator…", self._open_calculator,
                 bg=CNE, pady=px(5)).pack(side="left", padx=(px(8), 0))
        self.issues = tk.Label(mid, text="", bg=CCA, fg=CRD, font=F_SM,
                               justify="left", anchor="w", wraplength=px(980))
        self.issues.pack(fill="x", pady=(px(8), 0))

        low = tk.Frame(body, bg=CBG)
        low.pack(fill="both", expand=True, pady=(px(10), 0))
        wcols = ("code", "qty", "area", "weight", "source")
        self.wraps = ttk.Treeview(low, columns=wcols, show="headings",
                                  style="TAF.Treeview", selectmode="extended")
        for col, (txt, wd) in {"code": ("Wrap page", 110),
                               "qty": ("Qty in wrap", 90),
                               "area": ("Area", 140),
                               "weight": ("Weight (kg)", 120),
                               "source": ("Where the weight came from", 340)
                               }.items():
            self.wraps.heading(col, text=txt, anchor="w")
            self.wraps.column(col, width=px(wd), anchor="w",
                              stretch=col == "source")
        self.wraps.tag_configure("over", foreground=CRD)
        self.wraps.pack(side="left", fill="both", expand=True)
        side = tk.Frame(low, bg=CBG, padx=px(10))
        side.pack(side="left", fill="y")
        flat_btn(side, "Record weight…", self._record_weight, bg=CA,
                 pady=px(5)).pack(fill="x")
        flat_btn(side, "Clear weight", lambda: self._record_weight(clear=True),
                 bg=CNE, pady=px(5)).pack(fill="x", pady=(px(6), 0))

        self._evals = []
        self._refresh()
        if self.items:
            self.lines.selection_set("0")

    # ── drawing ─────────────────────────────────────────────────────────
    def _refresh(self, keep: "str | None" = None):
        try:
            wraps = _order_packing.order_wraps(self.items, self.settings)
        except Exception as exc:
            self.status.set(f"Could not work out the packing: {exc}")
            return
        self._order_lines = wraps["lines"]
        for iid in self.lines.get_children():
            self.lines.delete(iid)
        for i, line in enumerate(self._order_lines):
            ev = line["eval"] or {}
            plan = ev.get("plan") or {}
            calc = ev.get("calc") or {}
            brace = (calc.get("bracing") or {}).get("message", "")
            text = "  ".join(ev.get("instructions") or []) or "—"
            if plan:
                text = ("Manual: " if plan.get("mode") == "manual"
                        else "Automatic: ") + text
            status = {"ok": "Ready", "needs_weight_check": "Weigh the wraps",
                      "conflict": "Needs a decision",
                      "invalid_plan": "Plan does not add up",
                      "needs_packing_input": "Set the packing",
                      "single_item_exception": "One filter is over 10 kg"
                      }.get(ev.get("status"), ev.get("status") or "")
            bad = ev.get("status") in ("conflict", "invalid_plan",
                                       "needs_packing_input",
                                       "single_item_exception")
            self.lines.insert("", "end", iid=str(i), tags=("problem",)
                              if bad else (), values=(
                i + 1, _line_size(line["item"]),
                line["item"].get("Quantity", line["item"].get("quantity", "")),
                text, len(line["wraps"]), status, brace))
        if keep is not None and self.lines.exists(keep):
            self.lines.selection_set(keep)
        self._show_line()

    def _selected(self) -> "int | None":
        sel = self.lines.selection()
        return int(sel[0]) if sel else None

    def _show_line(self):
        idx = self._selected()
        for iid in self.wraps.get_children():
            self.wraps.delete(iid)
        if idx is None or idx >= len(self._order_lines):
            return
        line = self._order_lines[idx]
        ev = line["eval"] or {}
        plan = ev.get("plan") or {}
        self.mode.set(plan.get("mode") or "automatic")
        self.per_wrap.set(str(plan.get("max_per_wrap") or ""))
        self.n_wraps.set("")
        self.explicit.set(", ".join(str(w["quantity"])
                                    for w in plan.get("wraps") or [])
                          if plan.get("mode") == "manual" else "")
        self.areas.set("; ".join(f"{g['name']} = {g['quantity']}"
                                 for g in plan.get("groups") or []))
        self.awkward.set(bool(plan.get("awkward")))
        issues = list(ev.get("issues") or [])
        prop = ev.get("proposal") or {}
        if ev.get("status") == "conflict" and prop.get("wraps"):
            issues.append("Suggested: " + _packing.instruction(
                [w["quantity"] for w in prop["wraps"]]))
        self.issues.config(text="\n".join(issues),
                           fg=CRD if ev.get("status") not in (
                               "ok", "needs_weight_check") else CMU)
        for w in line["wraps"]:
            weight = w.get("weight") or {}
            src = {"measured": f"Weighed by {w.get('measured_by') or '—'}",
                   "calculated": "Calculated from the filter weight",
                   "unknown": "Not known: " + ", ".join(
                       weight.get("missing") or [])}.get(
                weight.get("source"), "")
            over = (weight.get("raw_kg") or 0) > _packing.MAX_BUNDLE_KG + 1e-9
            self.wraps.insert("", "end", iid=w.get("id") or "",
                              tags=("over",) if over else (), values=(
                w.get("code", ""), w.get("quantity", ""),
                w.get("group") or "", weight.get("display") or "____",
                src))

    # ── saving ──────────────────────────────────────────────────────────
    def _persist(self, idx: int, plan: dict) -> bool:
        item = self.items[idx]
        if self.order_id:
            try:
                saved = _db.set_line_fields(str(self.order_id),
                                            item.get(_db.LINE_ID) or "",
                                            {"Packing": plan})
            except Exception as exc:
                messagebox.showerror("Packing", str(exc), parent=self)
                return False
            self.items = saved
            try:
                _db.log_action("packing_set",
                               f"O/N: {self.row.get('order_no','')} | "
                               f"Line {idx + 1} | "
                               + " ".join(_packing.plan_instructions(plan)))
            except Exception:
                pass
        else:
            item["Packing"] = plan
        if self.on_saved:
            self.on_saved(self.items)
        self._refresh(keep=str(idx))
        return True

    def _save_line(self):
        idx = self._selected()
        if idx is None:
            messagebox.showinfo("Packing", "Choose a line first.", parent=self)
            return
        item = self.items[idx]
        who, at = _who_now(), _calc_settings.now_iso()
        try:
            groups = _packing.parse_groups(self.areas.get())
            if self.mode.get() == "manual":
                if groups:
                    rows = _packing.grouped_rows(groups, self.per_wrap.get())
                    if self.explicit.get().strip():
                        raise _packing.PackingError(
                            "With customer areas, give filters per wrap - "
                            "each area is wrapped separately.")
                    plan = _order_packing.set_manual(
                        item, [r["quantity"] for r in rows], groups=groups,
                        group_of_wrap=[r["group"] for r in rows], by=who,
                        at=at)
                else:
                    qty = _order_packing._quantity(item)
                    plan = _order_packing.set_manual(
                        item, _packing.quantities_from_form(
                            qty, self.per_wrap.get(), self.n_wraps.get(),
                            self.explicit.get()), by=who, at=at)
            else:
                plan = _order_packing.set_automatic(
                    item, self.settings, max_per_wrap=self.per_wrap.get()
                    or None, groups=groups, awkward=self.awkward.get(),
                    by=who, at=at)
                if plan is None:
                    raise _packing.PackingError(
                        "There is not enough to plan this automatically - "
                        "set filters per wrap, or choose Manual.")
            plan["awkward"] = bool(self.awkward.get())
        except _packing.PackingError as exc:
            messagebox.showwarning("Packing", str(exc), parent=self)
            return
        if self._persist(idx, plan):
            self.status.set(f"Line {idx + 1} saved.")

    def _use_proposal(self):
        idx = self._selected()
        if idx is None:
            return
        prop = (self._order_lines[idx]["eval"] or {}).get("proposal") or {}
        if not prop.get("wraps"):
            messagebox.showinfo("Packing", "There is no other plan to suggest.",
                                parent=self)
            return
        self.mode.set("manual")
        self.per_wrap.set("")
        self.n_wraps.set("")
        self.explicit.set(", ".join(str(w["quantity"]) for w in prop["wraps"]))

    def _record_weight(self, clear: bool = False):
        idx = self._selected()
        sel = self.wraps.selection()
        if idx is None or len(sel) != 1:
            messagebox.showinfo("Weight", "Choose one wrap.", parent=self)
            return
        wrap_id = sel[0]
        if not self.items[idx].get("Packing"):
            # An automatic plan nobody has saved yet: save it first (with the
            # wrap ids on screen), so the weight belongs to a wrap that will
            # still exist tomorrow.
            ev = self._order_lines[idx]["eval"] or {}
            if not ev.get("plan") or not self._persist(idx, ev["plan"]):
                return
        plan = self.items[idx].get("Packing") or {}
        text = ""
        if not clear:
            text = simpledialog.askstring(
                "Weigh this wrap",
                "Weight of the wrapped bundle in kg, wrapping included:",
                parent=self) or ""
            if not text.strip():
                return
        try:
            plan = _packing.record_weight(plan, wrap_id, text, _who_now(),
                                          _calc_settings.now_iso())
        except _packing.PackingError as exc:
            messagebox.showwarning("Weight", str(exc), parent=self)
            return
        kg = _packing.positive(text) if text else None
        if self._persist(idx, plan) and kg and kg > _packing.MAX_BUNDLE_KG:
            messagebox.showwarning(
                "Over 10 kg", f"That wrap weighs {text} kg - over the 10 kg "
                "limit. Repack it into smaller wraps and weigh them again.",
                parent=self)

    def _open_calculator(self):
        idx = self._selected()
        if idx is None:
            return
        item = self.items[idx]
        if not item.get("Filter Type"):
            messagebox.showinfo("Weight calculator",
                                "The calculator is for filter lines.",
                                parent=self)
            return

        def _saved(inputs):
            if self.order_id:
                try:
                    self.items = _db.set_line_fields(
                        str(self.order_id), item.get(_db.LINE_ID) or "",
                        {"Calculator": inputs or None})
                except Exception as exc:
                    messagebox.showerror("Weight calculator", str(exc),
                                         parent=self)
                    return
            else:
                item["Calculator"] = inputs
            if self.on_saved:
                self.on_saved(self.items)
            self._refresh(keep=str(idx))

        FilterCalculatorDialog(self, item, self.settings, on_save=_saved)

    # ── labels ──────────────────────────────────────────────────────────
    def _order_record(self) -> dict:
        return {"order_number": self.row.get("order_no") or
                self.header.get("Order Number", ""),
                "customer_name": self.row.get("customer") or
                self.header.get("Customer Name", ""),
                "customer_id": self.row.get("customer_id") or "",
                "header": self.header}

    def _print_all(self):
        unsaved = [i + 1 for i, it in enumerate(self.items)
                   if not it.get("Packing")]
        if unsaved and self.order_id:
            if not messagebox.askyesno(
                    "Delivery labels",
                    "Lines " + ", ".join(map(str, unsaved)) + " have no "
                    "saved packing yet. Save the automatic plan for them and "
                    "print?", parent=self):
                return
            for i in [n - 1 for n in unsaved]:
                ev = self._order_lines[i]["eval"] or {}
                if ev.get("plan"):
                    if not self._persist(i, ev["plan"]):
                        return
        print_delivery_labels(self, self._order_record(), self.items)

    def _print_selected(self):
        ids = [i for i in self.wraps.selection() if i]
        if not ids:
            messagebox.showinfo("Reprint", "Choose the wraps to reprint.",
                                parent=self)
            return
        print_delivery_labels(self, self._order_record(), self.items,
                              only_wrap_ids=ids)


class FilterCalculatorDialog(tk.Toplevel):
    """Cut sizes and weights for one line, and the measured inputs behind them.

    The same calculation the worksheet, the packing plan and the labels use.
    What is entered here - a measured cut, a confirmed retention, a wire
    choice - is saved on the line, so all of those pick it up.
    """

    def __init__(self, master, item: dict, settings: dict, on_save=None,
                 editable: bool = True):
        super().__init__(master)
        self.title("Weight calculator")
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.item = dict(item)
        self.settings = settings
        self.on_save = on_save
        _centre_on_parent(self, master, px(860), px(640))
        self.bind("<Escape>", lambda _e: self.destroy())
        saved = dict(item.get("Calculator") or {})

        top = tk.Frame(self, bg=CA, padx=px(16), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text=f"Weight calculator — {item.get('Quantity','')} x "
                           f"{item.get('Filter Type','')} {_line_size(item)} "
                           f"{item.get('Media Type','')}",
                 bg=CA, fg="white", font=(FAM, 12, "bold")).pack(anchor="w")

        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Close", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        if editable and on_save:
            flat_btn(foot, "Save to this line", self._save, bg=CGR,
                     pady=px(6)).pack(side="right", padx=(0, px(8)))
        flat_btn(foot, "Recalculate", self._recalc, bg=CA,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))

        form = tk.Frame(self, bg=CCA, padx=px(14), pady=px(10),
                        highlightbackground=CBR, highlightthickness=1)
        form.pack(fill="x", padx=px(14), pady=(px(10), 0))
        wire = saved.get("wire") or {}
        self.wire_code = tk.StringVar(value=saved.get("wire_material_override")
                                      or "Automatic")
        self.wire_pieces = tk.StringVar(value="; ".join(
            f"{p['cut_width_mm']:g} x {p['cut_length_mm']:g} x "
            f"{p['pieces_per_filter']}" for p in wire.get("pieces") or []))
        self.wire_kept = tk.StringVar(value=self._kept_text(wire.get("installed")))
        comps = saved.get("media_components") or []
        media = comps[0] if comps else {}
        self.media_pieces = tk.StringVar(value="; ".join(
            f"{p['cut_width_mm']:g} x {p['cut_length_mm']:g} x "
            f"{p['pieces_per_filter']}" for p in media.get("pieces") or []))
        self.media_kept = tk.StringVar(value=self._kept_text(media.get("installed")))
        self.extra = tk.StringVar(value="; ".join(
            f"{c['name']} = " + ("n/a" if c.get("not_applicable")
                                 else f"{c.get('kg_per_filter')}")
            for c in saved.get("components") or []))
        kept_choices = ["Not confirmed", "Whole blank stays in the filter"]
        rows = [
            ("Wire", ttk.Combobox(form, textvariable=self.wire_code,
                                  values=["Automatic", "LARGE_WIRE",
                                          "SMALL_WIRE"], state="readonly",
                                  width=14)),
            ("Measured wire cuts (W x L x pieces; ...)",
             field_entry(form, textvariable=self.wire_pieces, width=40)),
            ("Wire kept in the filter", ttk.Combobox(
                form, textvariable=self.wire_kept, values=kept_choices,
                state="readonly", width=30)),
            ("Measured media cuts (W x L x pieces; ...)",
             field_entry(form, textvariable=self.media_pieces, width=40)),
            ("Media kept in the filter", ttk.Combobox(
                form, textvariable=self.media_kept, values=kept_choices,
                state="readonly", width=30)),
            ("Other parts (name = kg each, or n/a; ...)",
             field_entry(form, textvariable=self.extra, width=40)),
        ]
        for r, (label, widget) in enumerate(rows):
            tk.Label(form, text=label, bg=CCA, fg=CMU, font=F_SM,
                     anchor="w").grid(row=r, column=0, sticky="w",
                                      pady=px(2), padx=(0, px(10)))
            widget.grid(row=r, column=1, sticky="ew", pady=px(2))
        form.columnconfigure(1, weight=1)

        self.out = tk.Text(self, wrap="word", font=F_BODY, bg=CCA, fg=CTX,
                           relief="flat", highlightthickness=1,
                           highlightbackground=CBR, padx=px(10), pady=px(8))
        self.out.pack(fill="both", expand=True, padx=px(14), pady=px(10))
        self.out.tag_configure("bold", font=F_BOLD)
        self.out.tag_configure("warn", foreground=CRD, font=F_BOLD)
        self._recalc()

    @staticmethod
    def _kept_text(rule) -> str:
        if rule == "full_blank" or (isinstance(rule, dict)
                                    and rule.get("rule") == "full_blank"):
            return "Whole blank stays in the filter"
        return "Not confirmed"

    def _inputs(self) -> dict:
        out: dict = {}
        if self.wire_code.get() not in ("", "Automatic"):
            out["wire_material_override"] = self.wire_code.get()
        wire: dict = {}
        if self.wire_pieces.get().strip():
            wire["pieces"] = _filter_calc.parse_pieces(self.wire_pieces.get())
        if self.wire_kept.get().startswith("Whole"):
            wire["installed"] = "full_blank"
        if wire:
            out["wire"] = wire
        media_code = str(self.item.get("Media Type") or "").strip()
        comp: dict = {"media_code": media_code}
        if self.media_pieces.get().strip():
            comp["pieces"] = _filter_calc.parse_pieces(self.media_pieces.get())
        if self.media_kept.get().startswith("Whole"):
            comp["installed"] = "full_blank"
        if len(comp) > 1 and media_code:
            out["media_components"] = [comp]
        extras = []
        for chunk in self.extra.get().split(";"):
            if not chunk.strip():
                continue
            if "=" not in chunk:
                raise ValueError(f"Write other parts as name = kg (not "
                                 f"{chunk.strip()!r}).")
            name, val = [x.strip() for x in chunk.split("=", 1)]
            if val.lower() in ("n/a", "na", "none"):
                extras.append({"name": name, "not_applicable": True})
            else:
                kg = _packing.positive(val) if val not in ("0",) else 0.0
                if kg is None:
                    raise ValueError(f"{name}: {val!r} is not a weight.")
                extras.append({"name": name, "kg_per_filter": kg})
        if extras:
            out["components"] = extras
        return out

    def _recalc(self):
        self.out.config(state="normal")
        self.out.delete("1.0", "end")
        try:
            inputs = self._inputs()
        except ValueError as exc:
            self.out.insert("end", str(exc), "warn")
            self.out.config(state="disabled")
            return
        trial = dict(self.item, Calculator=inputs)
        r = _filter_calc.calculate_item(trial, self.settings)
        from taf_order_app import worksheet_blocks as _wb
        for text, bold in _wb.calculator_lines({"calc": r}):
            if text.startswith("Weight incomplete"):
                continue          # listed in full just below
            self.out.insert("end", text + "\n", "bold" if bold else "")
        missing = list(dict.fromkeys(r.get("missing") or []))
        if missing:
            self.out.insert("end", "\nStill needed for a complete weight:\n",
                            "warn")
            for m in missing:
                self.out.insert("end", f"  • {m}\n")
        self.out.insert("end", "\nWorked out with: " + ", ".join(
            f"{k} {v}" for k, v in (r.get("provenance") or {}).items()
            if not isinstance(v, dict)) + "\n")
        self.out.config(state="disabled")
        self._result = r

    def _save(self):
        try:
            inputs = self._inputs()
        except ValueError as exc:
            messagebox.showwarning("Weight calculator", str(exc), parent=self)
            return
        if self.on_save:
            self.on_save(inputs)
        self.destroy()


class WeightsSettingsDialog(tk.Toplevel):
    """The numbers behind weights, packing and labels, for everyone.

    Managers change them; everyone else sees them. Each save is a new
    version - the old value stays in the history - so a weight can always
    be traced to the numbers it came from.
    """

    def __init__(self, master, editable: bool):
        super().__init__(master)
        self.title("Weights, packing and labels")
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.editable = editable
        self.s = _calc_settings.cached()
        _centre_on_parent(self, master, px(1060), px(720))
        self.bind("<Escape>", lambda _e: self.destroy())

        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Close", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        tk.Label(foot, text="" if editable else
                 "Only a manager can change these.", bg=CBG, fg=CMU,
                 font=F_SM).pack(side="left")

        nb = ttk.Notebook(self)
        nb.pack(fill="both", expand=True, padx=px(14), pady=px(10))
        self._company(nb)
        self._materials(nb)
        self._packing_tab(nb)
        self._cchannel_tab(nb)
        self._frames_tab(nb)
        for section, title, hint in (
                ("steel", "Steel",
                 '{"density_kg_m3": ..., "basis": "...", "material": '
                 '"galvanised steel stock"} - the confirmed density of the '
                 'steel stock, used for mounting frames.'),
                ("wire_rules", "Wire choice",
                 'Which wire each non-V-form filter is made with, e.g. '
                 '{"Flat Panel": "SMALL_WIRE"}. V-forms go by depth.'),
                ("cut_profiles", "Cut profiles",
                 'Confirmed cut profiles that replace or add to the '
                 'worksheet formulas (see the README).'),
                ("mounting_frame_profiles", "Mounting frames",
                 'Verified profiles: sizes, pieces (strip width, retained '
                 'length, qty), holes, overlaps and hardware. Known sizes: '
                 + ", ".join(f"{z['width_mm']}x{z['height_mm']}"
                             for z in _mounting_frames.known_sizes()))):
            self._json_tab(nb, section, title, hint)

    def _page(self, nb, title):
        f = tk.Frame(nb, bg=CCA, padx=px(14), pady=px(12))
        nb.add(f, text=f"  {title}  ")
        return f

    def _store(self, section, value, quiet: bool = False) -> bool:
        if not self.editable:
            return False
        try:
            version = _calc_settings.save(section, value)
            self.s = _calc_settings.load(force=True)
            _db.log_action("calc_setting_changed",
                           f"{section} -> version {version}")
        except Exception as exc:
            messagebox.showerror("Settings", f"Not saved:\n{exc}", parent=self)
            return False
        if not quiet:
            messagebox.showinfo("Settings", "Saved for everyone. New "
                                "worksheets and labels use it from now on.",
                                parent=self)
        return True

    def _company(self, nb):
        f = self._page(nb, "Company")
        tk.Label(f, text="Base address — the From line on every delivery "
                         "label", bg=CCA, fg=CTX, font=F_BOLD).pack(anchor="w")
        var = tk.StringVar(value=_calc_settings.base_address(self.s))
        e = field_entry(f, textvariable=var, width=80)
        e.pack(fill="x", pady=(px(6), px(6)))
        if not self.editable:
            e.config(state="disabled")
        tk.Label(f, text=f"{_calc_settings.COMPANY['name']}   ·   ABN "
                         f"{_calc_settings.COMPANY['abn']}   ·   "
                         f"{_calc_settings.COMPANY['phone']}",
                 bg=CCA, fg=CMU, font=F_SM).pack(anchor="w")

        def _save():
            text = var.get().strip()
            if not text:
                messagebox.showwarning("Base address", "The address can't be "
                                       "empty.", parent=self)
                return
            company = dict(self.s.get("company") or {})
            company["base_address"] = text
            self._store("company", company)
        if self.editable:
            flat_btn(f, "Save address", _save, bg=CGR,
                     pady=px(5)).pack(anchor="w", pady=(px(10), 0))

    def _materials(self, nb):
        f = self._page(nb, "Wire and media")
        cols = ("code", "kind", "mass", "area", "rate", "basis")
        tree = ttk.Treeview(f, columns=cols, show="headings", height=9,
                            style="TAF.Treeview")
        for col, (txt, wd) in {"code": ("Code", 110), "kind": ("Kind", 70),
                               "mass": ("Stock kg", 90),
                               "area": ("Stock m²", 90),
                               "rate": ("kg/m²", 120),
                               "basis": ("Basis", 260)}.items():
            tree.heading(col, text=txt, anchor="w")
            tree.column(col, width=px(wd), anchor="w")
        tree.pack(fill="both", expand=True)

        def _fill():
            mats = self.s["materials"]
            for iid in tree.get_children():
                tree.delete(iid)
            for code in _filter_calc._mat.WIRE_CODES:
                m = _filter_calc._mat.wire_material(code, mats)
                tree.insert("", "end", iid="wire:" + code, values=(
                    code, "wire", f"{m['roll_weight_kg']:g}",
                    f"{m['roll_area_m2']:g}", f"{m['kg_per_m2']:.6f}",
                    m["basis"]))
            for code in _filter_calc._mat.MEDIA_CODES:
                m = _filter_calc._mat.media_material(code, mats)
                tree.insert("", "end", iid="media:" + code, values=(
                    code, "media", f"{m['stock_weight_kg']:g}",
                    f"{m['stock_area_m2']:g}", f"{m['kg_per_m2']:.6f}",
                    m["basis"]))
        _fill()

        def _edit():
            sel = tree.selection()
            if not sel:
                return
            kind, code = sel[0].split(":", 1)
            mats = self.s["materials"]
            row = mats[kind][code]
            mass_key = "roll_weight_kg" if kind == "wire" else "stock_weight_kg"
            mass = simpledialog.askstring(
                "Weighed stock", f"{code}: what the stock weighs, kg "
                "(as weighed)", parent=self,
                initialvalue=str(row.get(mass_key) or ""))
            if mass is None:
                return
            area_note = ("roll width x length is kept as supplied"
                         if kind == "wire" else "stock area in m²")
            area = None
            if kind == "media":
                area = simpledialog.askstring(
                    "Weighed stock", f"{code}: {area_note}", parent=self,
                    initialvalue=str(row.get("stock_area_m2") or ""))
                if area is None:
                    return
            try:
                if kind == "media" and code == "BLACK":
                    new = _filter_calc._mat.replace_black_with_measurement(
                        mats, mass, area, _who_now(),
                        _calc_settings.now_iso())
                else:
                    new = json.loads(json.dumps(mats))
                    value = float(mass)
                    if value <= 0:
                        raise ValueError
                    new[kind][code][mass_key] = value
                    new[kind][code]["basis"] = (
                        "supplied_roll_mass" if kind == "wire"
                        else "supplied_stock_mass")
                    if area is not None:
                        a = float(area)
                        if a <= 0:
                            raise ValueError
                        new[kind][code]["stock_area_m2"] = a
                    new[kind][code]["measured_by"] = _who_now()
                    new[kind][code]["measured_at"] = _calc_settings.now_iso()
            except (ValueError, TypeError, _filter_calc._mat.MaterialError):
                messagebox.showwarning("Weighed stock", "Both have to be "
                                       "numbers above zero.", parent=self)
                return
            new["version"] = f"{_filter_calc._mat.DEFAULTS_VERSION}+edit"
            if self._store("materials", new):
                _fill()
        if self.editable:
            flat_btn(f, "Enter a weighed roll for the selected row…", _edit,
                     bg=CA, pady=px(5)).pack(anchor="w", pady=(px(8), 0))
        tk.Label(f, text="Rates are worked out from the stock's weight and "
                         "size, never typed. BLACK follows GREY until a "
                         "BLACK roll is weighed.", bg=CCA, fg=CMU,
                 font=F_SM, wraplength=px(820), justify="left"
                 ).pack(anchor="w", pady=(px(6), 0))

    def _packing_tab(self, nb):
        f = self._page(nb, "Packing")
        pack = dict(self.s.get("packaging") or {})
        confirmed = tk.BooleanVar(value=bool(pack.get("confirmed")))
        base = tk.StringVar(value=str(pack.get("base_kg", "")))
        per = tk.StringVar(value=str(pack.get("per_filter_kg", "")))
        rounding = tk.StringVar(value=self.s.get("shipping_rounding") or "none")
        tk.Label(f, text="What the wrapping itself weighs", bg=CCA, fg=CTX,
                 font=F_BOLD).grid(row=0, column=0, columnspan=4, sticky="w")
        tk.Checkbutton(f, text="Count the wrapping at these weights (untick to leave label weights blank)",
                       variable=confirmed, bg=CCA, fg=CTX, font=F_BODY,
                       activebackground=CCA, selectcolor=CBG
                       ).grid(row=1, column=0, columnspan=4, sticky="w")
        for r, (label, var) in enumerate((("Per wrap, kg", base),
                                          ("Plus per filter, kg", per)), 2):
            tk.Label(f, text=label, bg=CCA, fg=CMU, font=F_SM
                     ).grid(row=r, column=0, sticky="w")
            field_entry(f, textvariable=var, width=10
                        ).grid(row=r, column=1, sticky="w", pady=px(2))
        tk.Label(f, text="Calculated weights on labels", bg=CCA, fg=CMU,
                 font=F_SM).grid(row=4, column=0, sticky="w", pady=(px(8), 0))
        ttk.Combobox(f, textvariable=rounding, state="readonly", width=34,
                     values=["none", "up_0.1"]).grid(row=4, column=1,
                                                     sticky="w",
                                                     pady=(px(8), 0))
        tk.Label(f, text="none = three decimal places;  up_0.1 = rounded up "
                         "to 0.1 kg, once, on the whole wrap", bg=CCA,
                 fg=CMU, font=F_SM).grid(row=5, column=0, columnspan=4,
                                         sticky="w")

        tk.Label(f, text="Handling limits (filters per wrap, by size)",
                 bg=CCA, fg=CTX, font=F_BOLD).grid(row=6, column=0,
                                                   columnspan=4, sticky="w",
                                                   pady=(px(14), 0))
        hp = list(self.s.get("handling_profiles") or [])
        lb = tk.Listbox(f, height=6, font=F_BODY, bg=CFD, relief="flat",
                        highlightthickness=0)
        lb.grid(row=7, column=0, columnspan=4, sticky="ew")
        f.columnconfigure(3, weight=1)

        def _fill():
            lb.delete(0, "end")
            for p in hp:
                m = p.get("match") or {}
                lb.insert("end", f"  {m.get('width_mm')} x {m.get('height_mm')}"
                                 f" x {m.get('depth_mm') or 'any'}  ->  "
                                 f"{p.get('max_per_wrap')} a wrap   "
                                 f"({p.get('source') or ''})")
        _fill()

        def _add():
            text = simpledialog.askstring(
                "Handling limit", "Width x height x depth, and the most per "
                "wrap - e.g. 412 x 412 x 90 = 5", parent=self)
            if not text:
                return
            m = re.match(r"^\s*(\d+)\s*[x×]\s*(\d+)\s*(?:[x×]\s*(\d+))?\s*"
                         r"=\s*(\d+)\s*$", text)
            if not m or int(m.group(4)) < 1:
                messagebox.showwarning("Handling limit", "Write it like "
                                       "412 x 412 x 90 = 5", parent=self)
                return
            hp.append({"id": f"HANDLING-{m.group(1)}x{m.group(2)}x"
                             f"{m.group(3) or 'any'}", "version": 1,
                       "verified": True,
                       "match": {"width_mm": int(m.group(1)),
                                 "height_mm": int(m.group(2)),
                                 "depth_mm": int(m.group(3))
                                 if m.group(3) else None},
                       "max_per_wrap": int(m.group(4)),
                       "source": f"set by {_who_now() or 'staff'}"})
            _fill()

        def _remove():
            sel = lb.curselection()
            if sel:
                hp.pop(sel[0])
                _fill()

        def _save():
            try:
                packaging = {"confirmed": bool(confirmed.get())}
                if base.get().strip():
                    packaging["base_kg"] = float(base.get())
                if per.get().strip():
                    packaging["per_filter_kg"] = float(per.get())
                if any(v < 0 for k, v in packaging.items()
                       if k != "confirmed"):
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Packing", "Wrapping weights are "
                                       "numbers, zero or more.", parent=self)
                return
            if self._store("packaging", packaging, quiet=True) and \
                    self._store("shipping_rounding", rounding.get(),
                                quiet=True):
                self._store("handling_profiles", hp)
        if self.editable:
            bar = tk.Frame(f, bg=CCA)
            bar.grid(row=8, column=0, columnspan=4, sticky="w",
                     pady=(px(8), 0))
            flat_btn(bar, "Add a limit…", _add, bg=CNE,
                     pady=px(5)).pack(side="left")
            flat_btn(bar, "Remove selected", _remove, bg=CNE,
                     pady=px(5)).pack(side="left", padx=(px(8), 0))
            flat_btn(bar, "Save packing settings", _save, bg=CGR,
                     pady=px(5)).pack(side="left", padx=(px(8), 0))

    # ── C-channel ─────────────────────────────────────────────────────────
    MATERIAL_FIELDS = (
        ("material", "Material", "text"),
        ("steel_grade", "Steel grade", "text"),
        ("galvanising", "Galvanising", "text"),
        ("nominal_thickness_mm", "Thickness, mm (as supplied)", "num"),
        ("thickness_basis", "That thickness is", "basis"),
        ("base_metal_thickness_mm", "Base-metal thickness, mm (if known)",
         "num"),
        ("coating_mass_g_m2", "Coating, g/m² (both sides)", "num"),
        ("density_kg_m3", "Steel density, kg/m³", "num"),
        ("stock_length_mm", "Stock length, mm", "num"),
        ("left_flange_mm", "Left flange, mm", "num"),
        ("right_flange_mm", "Right flange, mm", "num"),
        ("bend_correction_mm", "Bend correction to developed width, mm",
         "num"),
        ("mass_calibration_factor", "Measured-mass calibration factor",
         "num"),
    )
    BASES = {"nominal_supplied": "Nominal, as supplied",
             "base_metal": "Base metal (no zinc)",
             "coated": "Coated (zinc included)"}

    def _cchannel_tab(self, nb):
        f = self._page(nb, "C-channel")
        cc = json.loads(json.dumps(self.s.get("c_channel")
                                   or _cchannel.default_settings()))
        left = tk.Frame(f, bg=CCA)
        left.pack(side="left", fill="y", padx=(0, px(14)))
        right = tk.Frame(f, bg=CCA)
        right.pack(side="left", fill="both", expand=True)

        code = tk.StringVar(value=cc.get("default_material")
                            or _cchannel.DEFAULT_MATERIAL)
        row0 = tk.Frame(left, bg=CCA)
        row0.pack(fill="x")
        tk.Label(row0, text="Material code", bg=CCA, fg=CTX,
                 font=F_BOLD).pack(side="left")
        codes = ttk.Combobox(row0, textvariable=code, state="readonly",
                             width=26, values=sorted(cc["materials"]))
        codes.pack(side="left", padx=(px(6), 0))
        grid = tk.Frame(left, bg=CCA)
        grid.pack(fill="x", pady=(px(6), 0))
        fvars = {}
        for r, (key, label, kind) in enumerate(self.MATERIAL_FIELDS):
            tk.Label(grid, text=label, bg=CCA, fg=CMU, font=F_SM
                     ).grid(row=r, column=0, sticky="w", pady=px(1))
            var = tk.StringVar()
            fvars[key] = var
            if kind == "basis":
                w = ttk.Combobox(grid, textvariable=var, state="readonly",
                                 width=24, values=list(self.BASES.values()))
            else:
                w = field_entry(grid, textvariable=var, width=22)
            w.grid(row=r, column=1, sticky="w", pady=0)
            if not self.editable:
                w.config(state="disabled")
        coat = tk.BooleanVar()
        tk.Checkbutton(left, text="Add the zinc coating's mass (only once "
                                  "the steel's base-metal thickness is "
                                  "known)", variable=coat, bg=CCA, fg=CTX,
                       font=F_SM, activebackground=CCA, selectcolor=CBG,
                       wraplength=px(360), justify="left"
                       ).pack(anchor="w", pady=(px(4), 0))
        sub = tk.StringVar(value=str((cc.get("estimate_rule") or {})
                                     .get("subtract_mm", 2)))
        er = tk.Frame(left, bg=CCA)
        er.pack(fill="x", pady=(px(6), 0))
        tk.Label(er, text="Estimated centre width = depth less", bg=CCA,
                 fg=CMU, font=F_SM).pack(side="left")
        field_entry(er, textvariable=sub, width=5).pack(side="left",
                                                        padx=px(4))
        tk.Label(er, text="mm", bg=CCA, fg=CMU, font=F_SM).pack(side="left")

        def _load(*_):
            m = cc["materials"].get(code.get()) or {}
            for key, _label, kind in self.MATERIAL_FIELDS:
                v = m.get(key)
                if kind == "basis":
                    fvars[key].set(self.BASES.get(v or "nominal_supplied", ""))
                else:
                    fvars[key].set("" if v is None else str(v))
            coat.set(bool(m.get("include_coating_mass")))
        code.trace_add("write", _load)
        _load()

        def _store_material() -> bool:
            m = dict(cc["materials"].get(code.get()) or {})
            for key, label, kind in self.MATERIAL_FIELDS:
                text = fvars[key].get().strip()
                if kind == "text":
                    m[key] = text
                elif kind == "basis":
                    m[key] = next((k for k, v in self.BASES.items()
                                   if v == text), "nominal_supplied")
                else:
                    if not text:
                        m[key] = None
                        continue
                    try:
                        m[key] = float(text)
                    except ValueError:
                        messagebox.showwarning("C-channel", f"{label} has to "
                                               "be a number.", parent=self)
                        return False
            m["include_coating_mass"] = bool(coat.get())
            cc["materials"][code.get()] = m
            return True

        # Centre widths: every depth, where its width came from.
        tk.Label(right, text="Centre width for each nominal depth",
                 bg=CCA, fg=CTX, font=F_BOLD).pack(anchor="w")
        cols = ("depth", "width", "status")
        tree = ttk.Treeview(right, columns=cols, show="headings", height=9,
                            style="TAF.Treeview")
        for col, text, wd in (("depth", "Depth", 70), ("width", "Width", 70),
                              ("status", "Status", 220)):
            tree.heading(col, text=text, anchor="w")
            tree.column(col, width=px(wd), anchor="w")
        tree.pack(fill="both", expand=True)
        wbar = tk.Frame(right, bg=CCA)
        wbar.pack(fill="x", pady=(px(4), 0))

        def _fill():
            for iid in tree.get_children():
                tree.delete(iid)
            for d in _cchannel.depths({"c_channel": cc}):
                r = _cchannel.resolve_dimensions(d, settings={"c_channel": cc})
                tree.insert("", "end", iid=str(d), values=(
                    f"{d:g}", f"{r['actual_centre_width_mm']:g}"
                    if r["actual_centre_width_mm"] is not None else "",
                    _cchannel.STATUS_LABELS.get(r["verification_status"],
                                                "")))
        _fill()

        def _edit_width():
            sel = tree.selection()
            if not sel:
                return
            depth = sel[0]
            cur = (cc["centre_widths"].get(depth) or {})
            text = simpledialog.askstring(
                "Centre width", f"Actual centre width for the {depth}mm "
                "channel, in mm (blank to go back to the estimate)",
                parent=self, initialvalue=str(cur.get("width_mm") or ""))
            if text is None:
                return
            if not text.strip():
                cc["centre_widths"].pop(depth, None)
                _fill()
                return
            try:
                width = float(text)
                if width <= 0:
                    raise ValueError
            except ValueError:
                messagebox.showwarning("Centre width", "A width above zero, "
                                       "in mm.", parent=self)
                return
            verified = messagebox.askyesno(
                "Centre width", f"Has {width:g}mm been measured on the "
                f"{depth}mm channel TAF makes?\n\nYes marks it verified; No "
                "keeps it as supplied but unconfirmed.", parent=self)
            cc["centre_widths"][depth] = {
                "width_mm": width,
                "status": "verified" if verified else
                "supplied_unconfirmed_mapping",
                "source": f"set by {_who_now() or 'staff'}",
                "at": _calc_settings.now_iso()}
            _fill()

        def _verify():
            for depth in tree.selection():
                row = cc["centre_widths"].get(depth)
                if row and row.get("status") == "supplied_unconfirmed_mapping":
                    row.update(status="verified",
                               source=f"{row.get('source', '')}; confirmed "
                                      f"by {_who_now() or 'staff'}",
                               at=_calc_settings.now_iso())
            _fill()

        # Measured weights: one length weighed, used before the sum.
        tk.Label(right, text="Measured weights (used instead of the sum)",
                 bg=CCA, fg=CTX, font=F_BOLD).pack(anchor="w",
                                                   pady=(px(8), 0))
        mlist = tk.Listbox(right, height=3, font=F_SM, bg=CFD, relief="flat",
                           highlightthickness=0)
        mlist.pack(fill="x")
        mbar = tk.Frame(right, bg=CCA)
        mbar.pack(fill="x", pady=(px(4), 0))

        def _fill_measured():
            mlist.delete(0, "end")
            for m in cc.get("measured_weights") or []:
                mlist.insert("end", f"  {m.get('nominal_depth_mm')}mm x "
                                    f"{m.get('length_mm')}mm = {m.get('kg')} "
                                    f"kg  ({'verified' if m.get('verified') else 'not verified'})")
        _fill_measured()

        def _add_measured():
            text = simpledialog.askstring(
                "Measured weight", "Depth, length and weight - e.g. "
                "45 x 2440 = 0.95", parent=self)
            if not text:
                return
            m = re.match(r"^\s*(\d+(?:\.\d+)?)\s*[x×]\s*(\d+(?:\.\d+)?)\s*="
                         r"\s*(\d*\.?\d+)\s*(?:kg)?\s*$", text)
            if not m or min(float(m.group(i)) for i in (1, 2, 3)) <= 0:
                messagebox.showwarning("Measured weight", "Write it like "
                                       "45 x 2440 = 0.95", parent=self)
                return
            cc.setdefault("measured_weights", []).append({
                "material_code": code.get(),
                "nominal_depth_mm": float(m.group(1)),
                "length_mm": float(m.group(2)), "kg": float(m.group(3)),
                "verified": True, "by": _who_now(),
                "at": _calc_settings.now_iso()})
            _fill_measured()

        def _remove_measured():
            sel = mlist.curselection()
            if sel:
                cc["measured_weights"].pop(sel[0])
                _fill_measured()

        def _save():
            if not _store_material():
                return
            try:
                cc["estimate_rule"] = {"subtract_mm": float(sub.get())}
            except ValueError:
                messagebox.showwarning("C-channel", "The estimate rule takes "
                                       "a number of mm.", parent=self)
                return
            cc["default_material"] = code.get()
            if self._store("c_channel", cc):
                _fill()

        def _new_code():
            name = simpledialog.askstring(
                "New material", "Material code (it starts as a copy of "
                f"{code.get()})", parent=self)
            name = (name or "").strip().upper().replace(" ", "_")
            if not name or name in cc["materials"]:
                return
            cc["materials"][name] = dict(cc["materials"][code.get()],
                                         material_code=name)
            codes.config(values=sorted(cc["materials"]))
            code.set(name)

        buttons = tk.Frame(f, bg=CCA)
        buttons.pack(side="bottom", fill="x", pady=(px(8), 0), before=left)
        flat_btn(buttons, "Weight table…",
                 lambda: CChannelTableDialog(self, {"c_channel": cc}),
                 bg=CA, pady=px(5)).pack(side="right")
        if self.editable:
            flat_btn(buttons, "Save C-channel", _save, bg=CGR,
                     pady=px(5)).pack(side="left", padx=(0, px(6)))
            flat_btn(buttons, "New material code…", _new_code, bg=CNE,
                     pady=px(5)).pack(side="left")
            for bar, items in ((wbar, (("Edit width…", _edit_width),
                                       ("Mark verified", _verify))),
                               (mbar, (("Add measured…", _add_measured),
                                       ("Remove", _remove_measured)))):
                for text, fn in items:
                    flat_btn(bar, text, fn, bg=CNE, pady=px(3),
                             font=F_SM).pack(side="left", padx=(0, px(6)))

    # What the frames table writes: one profile for the steel channel, one
    # for the flyscreen frame, kept alongside any other part profiles.
    CHANNEL_ID = "TAF-CHANNEL"
    FLYSCREEN_FRAME_ID = "TAF-FLYSCREEN-FRAME"
    BRACED = ("Flat Panel", "V-form", "Flyscreen")

    def _frames_tab(self, nb):
        f = self._page(nb, "Frames and braces")
        profiles = [dict(p) for p in (self.s.get("component_profiles") or [])]
        channel = next((p for p in profiles
                        if p.get("id") == self.CHANNEL_ID), None) or {}
        fly = next((p for p in profiles
                    if p.get("id") == self.FLYSCREEN_FRAME_ID), None) or {}
        rates = {str(k): v for k, v in
                 (channel.get("kg_per_m_by_depth") or {}).items()}

        tk.Label(f, text="Steel channel - weigh one metre of each thickness",
                 bg=CCA, fg=CTX, font=F_BOLD).grid(row=0, column=0,
                                                   columnspan=4, sticky="w")
        tk.Label(f, text="A frame's channel is worked out from its size: "
                         "every side 2mm under, plus the two 20mm lips of a "
                         "U and its cap (a G is 20mm less, so this never "
                         "comes out light).", bg=CCA, fg=CMU, font=F_SM,
                 wraplength=px(820), justify="left"
                 ).grid(row=1, column=0, columnspan=4, sticky="w")
        lb = tk.Listbox(f, height=7, font=F_BODY, bg=CFD, relief="flat",
                        highlightthickness=0)
        lb.grid(row=2, column=0, columnspan=4, sticky="ew", pady=(px(4), 0))
        f.columnconfigure(3, weight=1)

        def _key(k):
            try:
                return float(k)
            except ValueError:
                return 0.0

        def _fill():
            lb.delete(0, "end")
            for depth in sorted(rates, key=_key):
                lb.insert("end", f"  {depth} mm channel  ->  "
                                 f"{rates[depth]:g} kg per metre")
            if not rates:
                lb.insert("end", "  Nothing entered yet - frame weights "
                                 "stay unknown until it is.")
        _fill()

        def _add():
            text = simpledialog.askstring(
                "Channel weight", "Channel thickness in mm, and what one "
                "metre of it weighs in kg - e.g. 25 = 0.62", parent=self)
            if not text:
                return
            m = re.match(r"^\s*(\d+(?:\.\d+)?)\s*(?:mm)?\s*=\s*"
                         r"(\d*\.?\d+)\s*(?:kg)?\s*$", text)
            if not m or float(m.group(1)) <= 0 or float(m.group(2)) <= 0:
                messagebox.showwarning("Channel weight", "Write it like "
                                       "25 = 0.62", parent=self)
                return
            rates[f"{float(m.group(1)):g}"] = float(m.group(2))
            _fill()

        def _remove():
            sel = lb.curselection()
            ordered = sorted(rates, key=_key)
            if sel and sel[0] < len(ordered):
                rates.pop(ordered[sel[0]], None)
                _fill()

        fly_var = tk.StringVar(value=str(fly.get("kg_per_m") or ""))
        tk.Label(f, text="Flyscreen frame, kg per metre (round the outside)",
                 bg=CCA, fg=CTX, font=F_BOLD).grid(row=4, column=0,
                                                   columnspan=2, sticky="w",
                                                   pady=(px(14), 0))
        fly_entry = field_entry(f, textvariable=fly_var, width=10)
        fly_entry.grid(row=4, column=2, sticky="w", pady=(px(14), 0))

        braces = {k: dict(v) for k, v in
                  (self.s.get("brace_profiles") or {}).items()}
        tk.Label(f, text="Braces - weight of one brace with its fixings, kg",
                 bg=CCA, fg=CTX, font=F_BOLD).grid(row=5, column=0,
                                                   columnspan=4, sticky="w",
                                                   pady=(px(14), 0))
        brace_vars = {}
        for r, name in enumerate(self.BRACED, 6):
            prof = braces.get(name) or {}
            kg = tk.StringVar(value=str(prof.get("kg_each_including_fixings")
                                        or ""))
            count = tk.StringVar(value=str(prof.get("count") or ""))
            brace_vars[name] = (kg, count)
            tk.Label(f, text=name, bg=CCA, fg=CMU, font=F_SM
                     ).grid(row=r, column=0, sticky="w")
            e1 = field_entry(f, textvariable=kg, width=10)
            e1.grid(row=r, column=1, sticky="w", pady=px(2))
            if name == "Flat Panel":
                tk.Label(f, text="how many: from the bracing rule", bg=CCA,
                         fg=CMU, font=F_SM).grid(row=r, column=2,
                                                 columnspan=2, sticky="w")
            else:
                tk.Label(f, text="how many when one is needed", bg=CCA,
                         fg=CMU, font=F_SM).grid(row=r, column=2, sticky="e")
                e2 = field_entry(f, textvariable=count, width=6)
                e2.grid(row=r, column=3, sticky="w", padx=(px(6), 0))
                if not self.editable:
                    e2.config(state="disabled")
            if not self.editable:
                e1.config(state="disabled")
        if not self.editable:
            fly_entry.config(state="disabled")
            return

        def _num(text, what, whole=False):
            text = str(text or "").strip()
            if not text:
                return None
            value = float(text)
            if value <= 0 or (whole and value != int(value)):
                raise ValueError(what)
            return int(value) if whole else value

        def _save():
            try:
                fly_kg = _num(fly_var.get(), "flyscreen frame")
                new_braces = dict(braces)
                for name, (kg, count) in brace_vars.items():
                    each = _num(kg.get(), name + " brace")
                    n = None if name == "Flat Panel" else \
                        _num(count.get(), name + " brace count", whole=True)
                    if each is None and n is None:
                        new_braces.pop(name, None)
                        continue
                    new_braces[name] = dict(
                        new_braces.get(name) or {},
                        kg_each_including_fixings=each, count=n,
                        set_by=_who_now(), set_at=_calc_settings.now_iso())
            except ValueError as exc:
                messagebox.showwarning("Frames and braces", f"{exc}: numbers "
                                       "above zero (a count is a whole "
                                       "number).", parent=self)
                return
            others = [p for p in profiles if p.get("id") not in
                      (self.CHANNEL_ID, self.FLYSCREEN_FRAME_ID)]
            if rates:
                others.append({
                    "name": "filter_frame", "id": self.CHANNEL_ID,
                    "version": int(channel.get("version") or 0) + 1,
                    "verified": True,
                    "constructions": ["Flat Panel", "Header", "V-form"],
                    "method": "channel_per_m",
                    "kg_per_m_by_depth": dict(rates),
                    "side_allowance_mm": 2, "lip_mm": 20, "lips": 2,
                    "basis": "weighed metre of channel",
                    "set_by": _who_now(), "set_at": _calc_settings.now_iso()})
            if fly_kg is not None:
                others.append({
                    "name": "flyscreen_frame", "id": self.FLYSCREEN_FRAME_ID,
                    "version": int(fly.get("version") or 0) + 1,
                    "verified": True, "constructions": ["Flyscreen"],
                    "method": "per_perimeter_m", "kg_per_m": fly_kg,
                    "basis": "weighed metre of flyscreen frame",
                    "set_by": _who_now(), "set_at": _calc_settings.now_iso()})
            if self._store("component_profiles", others, quiet=True):
                self._store("brace_profiles", new_braces)

        bar = tk.Frame(f, bg=CCA)
        bar.grid(row=3, column=0, columnspan=4, sticky="w", pady=(px(6), 0))
        flat_btn(bar, "Add a thickness…", _add, bg=CNE,
                 pady=px(5)).pack(side="left")
        flat_btn(bar, "Remove selected", _remove, bg=CNE,
                 pady=px(5)).pack(side="left", padx=(px(8), 0))
        flat_btn(f, "Save frames and braces", _save, bg=CGR, pady=px(5)
                 ).grid(row=9, column=0, columnspan=4, sticky="w",
                        pady=(px(12), 0))

    def _json_tab(self, nb, section, title, hint):
        f = self._page(nb, title)
        tk.Label(f, text=hint, bg=CCA, fg=CMU, font=F_SM, justify="left",
                 wraplength=px(820)).pack(anchor="w")
        txt = tk.Text(f, height=14, font=F_NUM, bg=CFD, fg=CTX,
                      relief="flat", wrap="none")
        txt.pack(fill="both", expand=True, pady=(px(6), 0))
        txt.insert("1.0", json.dumps(self.s.get(section), indent=2))
        if not self.editable:
            txt.config(state="disabled")
            return

        def _save():
            try:
                value = json.loads(txt.get("1.0", "end") or "null")
            except ValueError as exc:
                messagebox.showwarning(title, f"That is not valid JSON:\n{exc}",
                                       parent=self)
                return
            want = dict if section in ("brace_profiles", "steel",
                                       "wire_rules") else list
            if not isinstance(value, want):
                messagebox.showwarning(title, f"This setting is a "
                                       f"{'set of named entries' if want is dict else 'list'}.",
                                       parent=self)
                return
            if want is list and any(not isinstance(p, dict) for p in value):
                messagebox.showwarning(title, "Each profile is an object.",
                                       parent=self)
                return
            self._store(section, value)
        flat_btn(f, f"Save {title.lower()}", _save, bg=CGR,
                 pady=px(5)).pack(anchor="w", pady=(px(8), 0))


ADDRESS_FIELDS = ("delivery_address1", "delivery_city", "delivery_state",
                  "delivery_postcode")


def customer_needs_address(cust) -> bool:
    """True when an account has no delivery address a label could use:
    street, suburb, state and postcode all have to be there."""
    if not cust or not cust.get("id"):
        return False
    return any(not str(cust.get(k) or "").strip() for k in ADDRESS_FIELDS)


def customer_needs_region(cust) -> bool:
    """True when an account has not been given its Location - which run its
    orders go on (Local, North, Logan ...). Only the named regions count: an
    old free-typed suburb is not one."""
    if not cust or not cust.get("id"):
        return False
    return str(cust.get("region") or "").strip() not in _pn.REGION_NAMES


class FixOrderHeaderDialog(tk.Toplevel):
    """Before printing a saved order: what on it will stop the worksheets
    printing - a date that is not a date, no Location - with a box to put
    each right. Nothing is printed until it is, so no delivery labels or
    half an order go out for a sheet that then fails.

    result = the corrected header, or None when cancelled.
    """

    def __init__(self, master, header: dict, problems: list, title: str):
        super().__init__(master)
        self.title("Fix before printing")
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.resizable(False, False)
        self.header = dict(header)
        self.result = None
        self.bind("<Escape>", lambda _e: self.destroy())

        top = tk.Frame(self, bg=CRD, padx=px(16), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text="Fix before printing", bg=CRD, fg="white",
                 font=(FAM, 13, "bold")).pack(anchor="w")
        tk.Label(top, text=f"{title}\nThe worksheets would be refused, so "
                           "nothing has been printed yet.",
                 bg=CRD, fg="white", font=F_SM, justify="left",
                 wraplength=px(440)).pack(anchor="w")

        foot = tk.Frame(self, bg=CBG, padx=px(18), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Save and print", self._save, bg=CGR,
                 pady=px(6)).pack(side="right")
        flat_btn(foot, "Cancel", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))

        body = tk.Frame(self, bg=CBG, padx=px(18), pady=px(12))
        body.pack(fill="both", expand=True)
        self.vars = {}
        first = None
        for r, (key, msg) in enumerate(problems):
            tk.Label(body, text=msg, bg=CBG, fg=CRD, font=F_SM,
                     wraplength=px(440), justify="left", anchor="w").grid(
                row=2 * r, column=0, columnspan=2, sticky="w",
                pady=(px(6), 0))
            tk.Label(body, text=key, bg=CBG, fg=CTX, font=F_BODY,
                     anchor="w").grid(row=2 * r + 1, column=0, sticky="w",
                                      padx=(0, px(10)))
            var = tk.StringVar(value=str(header.get(key, "") or ""))
            self.vars[key] = var
            if key == "Location":
                w = ttk.Combobox(body, textvariable=var, state="readonly",
                                 values=list(_pn.REGION_NAMES), width=18)
            else:
                w = field_entry(body, textvariable=var, width=18)
            w.grid(row=2 * r + 1, column=1, sticky="w", pady=px(2))
            if first is None:
                first = w
        self.err = tk.Label(body, text="", bg=CBG, fg=CRD, font=F_SM,
                            anchor="w", wraplength=px(440), justify="left")
        self.err.grid(row=2 * len(problems), column=0, columnspan=2,
                      sticky="w", pady=(px(8), 0))
        self.bind("<Return>", lambda _e: self._save())
        self.update_idletasks()
        _centre_on_parent(self, master, max(px(500), self.winfo_reqwidth()),
                          self.winfo_reqheight())
        if first is not None:
            self.after(50, first.focus_set)

    def fixed(self) -> dict:
        out = dict(self.header)
        for key, var in self.vars.items():
            out[key] = var.get().strip()
        return out

    def _save(self):
        header = self.fixed()
        left = header_problems(header)
        if left:
            self.err.config(text="Still to fix:\n" + "\n".join(
                m for _k, m in left))
            return
        self.result = header
        self.destroy()


class AddAddressDialog(tk.Toplevel):
    """Add Address for "Customer" - the delivery address a customer account
    is missing, asked for on the order form as the customer is chosen, so
    the delivery labels have somewhere to send the order. An account with
    no Location yet is asked for that in the same window ("Choose Location
    for ..." when the address is already there).

    Saves to the customer's account. `on_saved(record)` gets the account as
    it now is.
    """

    def __init__(self, master, cust: dict, on_saved=None):
        super().__init__(master)
        self.cust = dict(cust)
        self.on_saved = on_saved
        self.need_address = customer_needs_address(cust)
        self.need_region = customer_needs_region(cust)
        name = cust.get("name") or "this customer"
        heading = (f'Add Address for "{name}"' if self.need_address
                   else f'Choose Location for "{name}"')
        self.title(heading)
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.resizable(False, False)
        self.bind("<Escape>", lambda _e: self.destroy())

        top = tk.Frame(self, bg=CA, padx=px(16), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text=heading, bg=CA, fg="white",
                 font=(FAM, 13, "bold")).pack(anchor="w")
        said = []
        if self.need_address:
            said.append("This customer has no delivery address yet. It goes "
                        "on their delivery labels.")
        if self.need_region:
            said.append("Their Location - which run their orders go on - "
                        "has not been chosen yet.")
        said.append("Saved to their account.")
        tk.Label(top, text=" ".join(said), bg=CA, fg="white", font=F_SM,
                 wraplength=px(420), justify="left").pack(anchor="w")

        # The buttons are packed before the fields so they always get their
        # room; a window sized a touch small loses a field's padding, never
        # the Save button.
        foot = tk.Frame(self, bg=CBG, padx=px(18), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Save address" if self.need_address else "Save",
                 self._save, bg=CGR, pady=px(6)).pack(side="right")
        flat_btn(foot, "Not now", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))

        body = tk.Frame(self, bg=CBG, padx=px(18), pady=px(12))
        body.pack(fill="both", expand=True)
        body.columnconfigure(1, weight=1)
        self.vars = {}
        rows = []
        if self.need_address:
            rows += [("delivery_address1", "Street address *"),
                     ("delivery_address2", "Address line 2"),
                     ("delivery_city", "Suburb *"),
                     ("delivery_state", "State *"),
                     ("delivery_postcode", "Postcode *")]
        if self.need_region:
            rows.append(("region", "Location *"))
        first = None
        r = 0
        for key, label in rows:
            tk.Label(body, text=label, bg=CBG, fg=CTX, font=F_BODY,
                     anchor="w").grid(row=r, column=0, sticky="w",
                                      pady=px(3), padx=(0, px(10)))
            start = str(cust.get(key) or "")
            if key == "region" and start not in _pn.REGION_NAMES:
                start = ""
            var = tk.StringVar(value=start)
            self.vars[key] = var
            if key in ("delivery_state", "region"):
                w = ttk.Combobox(body, textvariable=var, state="readonly",
                                 values=list(_db.AU_STATES)
                                 if key == "delivery_state"
                                 else list(_pn.REGION_NAMES),
                                 width=10 if key == "delivery_state" else 18)
                w.grid(row=r, column=1, sticky="w", pady=px(3))
                if key == "region":
                    hint = tk.Label(body, text="", bg=CBG, fg=CMU, font=F_SM,
                                    anchor="w")
                    r += 1
                    hint.grid(row=r, column=1, sticky="w")
                    var.trace_add("write", lambda *_a, v=var, h=hint: h.config(
                        text=_pn.REGIONS.get(v.get(), "")))
                    if first is None:
                        first = w
            else:
                w = field_entry(body, textvariable=var,
                                width=10 if key == "delivery_postcode" else 40)
                w.grid(row=r, column=1, sticky="w" if key ==
                       "delivery_postcode" else "ew", pady=px(3))
                if first is None:
                    first = w
            r += 1
        self.err = tk.Label(body, text="", bg=CBG, fg=CRD, font=F_SM,
                            anchor="w")
        self.err.grid(row=r, column=0, columnspan=2, sticky="w",
                      pady=(px(6), 0))

        self.bind("<Return>", lambda _e: self._save())
        self.update_idletasks()
        _centre_on_parent(self, master, max(px(520), self.winfo_reqwidth()),
                          self.winfo_reqheight())
        if first is not None:
            self.after(50, first.focus_set)

    def values(self) -> dict:
        return {k: v.get().strip() for k, v in self.vars.items()}

    def problems(self) -> list:
        v = self.values()
        out = []
        if self.need_address:
            for key, label in (("delivery_address1", "street address"),
                               ("delivery_city", "suburb"),
                               ("delivery_state", "state")):
                if not v[key]:
                    out.append(label)
            if not re.fullmatch(r"\d{4}", v["delivery_postcode"]):
                out.append("a four-digit postcode")
        if self.need_region and v.get("region") not in _pn.REGION_NAMES:
            out.append("their Location")
        return out

    def _save(self):
        missing = self.problems()
        if missing:
            self.err.config(text="Still needs: " + ", ".join(missing) + ".")
            return
        data = self.values()
        # An account whose billing follows its delivery address keeps doing
        # so; a separate billing address is left alone.
        if self.need_address and self.cust.get("billing_same", True):
            for part in ("address1", "address2", "city", "state", "postcode"):
                data[f"billing_{part}"] = data[f"delivery_{part}"]
        try:
            _db.update_customer(self.cust["id"], data)
        except Exception as exc:
            self.err.config(text=f"Not saved: {exc}")
            return
        try:
            what = " and ".join(
                w for w, on in (("Delivery address", self.need_address),
                                ("Location", self.need_region)) if on)
            _db.log_action("customer_updated",
                           f"{what} added for "
                           f"{self.cust.get('name', '')} from the order form")
        except Exception:
            pass
        self.cust.update(data)
        if self.on_saved:
            self.on_saved(self.cust)
        self.destroy()


class CChannelTableDialog(tk.Toplevel):
    """Every C-channel depth, what its channel is and what a stack weighs.

    Nothing in the table is typed: each row comes from the C-channel
    calculator (taf_order_app/cchannel.py) with the current settings. Stacks
    are worked out from the unrounded weight of one length and rounded up to
    the next 0.1 kg once.
    """

    COLS = ("depth", "size", "status", "one", "s1", "s2", "s5", "s10",
            "custom")

    def __init__(self, master, settings=None):
        super().__init__(master)
        self.title("C-channel weights")
        self.transient(master)
        self.configure(bg=CBG)
        self.settings = settings if settings is not None else \
            _calc_settings.cached()
        _centre_on_parent(self, master, px(1180), px(680))
        self.bind("<Escape>", lambda _e: self.destroy())

        top = tk.Frame(self, bg=CA, padx=px(16), pady=px(10))
        top.pack(fill="x")
        mat = _cchannel.material(self.settings) or {}
        tk.Label(top, text="C-channel weights", bg=CA, fg="white",
                 font=(FAM, 13, "bold")).pack(anchor="w")
        tk.Label(top, text=(f"{mat.get('material', '')}, "
                            f"{mat.get('nominal_thickness_mm', '')} mm, "
                            f"{mat.get('density_kg_m3', '')} kg/m³, "
                            f"{mat.get('left_flange_mm', '')} × centre × "
                            f"{mat.get('right_flange_mm', '')} mm. Stacks "
                            "rounded up to the next 0.1 kg."),
                 bg=CA, fg="white", font=F_SM).pack(anchor="w")

        bar = tk.Frame(self, bg=CBG, padx=px(14), pady=px(8))
        bar.pack(fill="x")
        self.search = tk.StringVar()
        self.status = tk.StringVar(value="All")
        self.custom = tk.StringVar(value="20")
        tk.Label(bar, text="Depth", bg=CBG, fg=CMU, font=F_SM).pack(side="left")
        field_entry(bar, textvariable=self.search, width=8).pack(
            side="left", padx=(px(4), px(14)))
        tk.Label(bar, text="Show", bg=CBG, fg=CMU, font=F_SM).pack(side="left")
        ttk.Combobox(bar, textvariable=self.status, state="readonly", width=30,
                     values=["All"] + list(_cchannel.STATUS_LABELS.values())
                     ).pack(side="left", padx=(px(4), px(14)))
        tk.Label(bar, text="Custom stack", bg=CBG, fg=CMU,
                 font=F_SM).pack(side="left")
        field_entry(bar, textvariable=self.custom, width=6).pack(
            side="left", padx=(px(4), 0))
        for v in (self.search, self.status, self.custom):
            v.trace_add("write", lambda *_: self._fill())

        wrap = tk.Frame(self, bg=CCA, highlightbackground=CBR,
                        highlightthickness=1)
        wrap.pack(fill="both", expand=True, padx=px(14))
        self.tree = ttk.Treeview(wrap, columns=self.COLS, show="headings",
                                 style="TAF.Treeview", selectmode="extended")
        heads = {"depth": ("Depth", 70), "size": ("Actual C-channel size", 175),
                 "status": ("Centre width", 165), "one": ("1 length (raw)", 115),
                 "s1": ("Stack of 1", 85), "s2": ("Stack of 2", 85),
                 "s5": ("Stack of 5", 85), "s10": ("Stack of 10", 90),
                 "custom": ("Custom", 90)}
        for col, (text, wd) in heads.items():
            self.tree.heading(col, text=text, anchor="w")
            self.tree.column(col, width=px(wd), minwidth=px(wd), anchor="w",
                             stretch=False)
        sb = ttk.Scrollbar(wrap, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tree.pack(fill="both", expand=True)
        self.tree.tag_configure("verified", foreground=CGR)
        self.tree.tag_configure("estimate", foreground="#B26A00")
        self.tree.bind("<Control-c>", lambda _e: self._copy())

        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Close", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        flat_btn(foot, "Export CSV…", self._export, bg=CA,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))
        flat_btn(foot, "Copy selected", self._copy, bg=CNE,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))
        self.note = tk.Label(foot, text="", bg=CBG, fg=CMU, font=F_SM)
        self.note.pack(side="left")
        self.rows = []
        self._fill()

    def _custom_qty(self):
        from taf_order_app.numbers import positive_int
        return positive_int(self.custom.get())

    def _fill(self):
        qty = self._custom_qty()
        qs = [1, 2, 5, 10] + ([qty] if qty else [])
        rows = _cchannel.table(self.settings, qs)
        want = self.search.get().strip()
        label = self.status.get()
        self.rows = []
        for iid in self.tree.get_children():
            self.tree.delete(iid)
        for r in rows:
            if want and not str(r["nominal_depth_mm"]).startswith(want):
                continue
            shown = _cchannel.STATUS_LABELS.get(r["verification_status"], "")
            if label != "All" and shown != label:
                continue
            stacks = [_cchannel.kg_text(x["stack_display_weight_kg"])
                      for x in r["stacks"]]
            if not qty:
                stacks.append("")
            values = (f"{r['nominal_depth_mm']:g} mm", r["size"], shown,
                      "" if r["raw_weight_kg"] is None
                      else f"{r['raw_weight_kg']:.6f} kg", *stacks)
            tag = "verified" if r["verification_status"] == "verified" else \
                "estimate" if r["verification_status"] in (
                    "estimated", "provisional_estimate") else ""
            self.tree.insert("", "end", iid=str(len(self.rows)),
                             values=values, tags=(tag,) if tag else ())
            self.rows.append(values)
        self.tree.heading("custom", text=f"Stack of {qty}" if qty else
                          "Custom")
        self.note.config(text=f"{len(self.rows)} depths shown")

    def _lines(self, rows):
        head = [self.tree.heading(c)["text"] for c in self.COLS]
        return [head] + [list(r) for r in rows]

    def _copy(self):
        sel = self.tree.selection() or self.tree.get_children()
        rows = [self.rows[int(i)] for i in sel]
        text = "\n".join("\t".join(str(v) for v in line)
                         for line in self._lines(rows))
        self.clipboard_clear()
        self.clipboard_append(text)
        self.note.config(text=f"Copied {len(rows)} row"
                              f"{'' if len(rows) == 1 else 's'}")

    def _export(self):
        import csv
        path = filedialog.asksaveasfilename(
            parent=self, title="Save C-channel weights",
            defaultextension=".csv", initialfile="c_channel_weights.csv",
            filetypes=[("CSV", "*.csv")])
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8-sig") as fh:
            csv.writer(fh).writerows(self._lines(self.rows))
        self.note.config(text=f"Saved {path}")


class PalletLabelsDialog(tk.Toplevel):
    """Pallet labels for one order, or several sharing the pallets: how many
    pallets, and how many of each line go on each. One sheet per pallet -
    see taf_order_app/pallet_labels.

    `add_order()` (optional) is asked for another order to put on the same
    pallets; it returns {"order", "items", "customer"} or None.
    """

    MAX_PALLETS = 40

    def __init__(self, master, order: dict, items: list, customer=None,
                 add_order=None, more=None):
        super().__init__(master)
        self.title("Pallet labels")
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.entries = [{"order": order, "items": list(items),
                         "customer": customer}] + list(more or [])
        self.add_order = add_order
        self.cells: list = []
        _centre_on_parent(self, master, px(1020), px(640))
        self.bind("<Escape>", lambda _e: self.destroy())

        top = tk.Frame(self, bg=CA, padx=px(16), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text="Pallet labels", bg=CA, fg="white",
                 font=(FAM, 13, "bold")).pack(anchor="w")
        self.subtitle = tk.Label(top, text="", bg=CA, fg="white", font=F_SM,
                                 justify="left", anchor="w")
        self.subtitle.pack(anchor="w")

        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Close", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        flat_btn(foot, "Print pallet labels", self._print, bg=CGR,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))
        self.note = tk.Label(foot, text="", bg=CBG, fg=CMU, font=F_SM,
                             justify="left", wraplength=px(560))
        self.note.pack(side="left")

        bar = tk.Frame(self, bg=CBG, padx=px(14), pady=px(8))
        bar.pack(fill="x")
        tk.Label(bar, text="How many pallets", bg=CBG, fg=CTX,
                 font=F_BOLD).pack(side="left")
        self.count = tk.StringVar(value="1")
        tk.Spinbox(bar, from_=1, to=self.MAX_PALLETS, width=4,
                   textvariable=self.count, font=F_BODY,
                   command=self._rebuild).pack(side="left", padx=(px(6),
                                                                   px(14)))
        self.count.trace_add("write", lambda *_: self.after(10, self._rebuild))
        for text, fn in (("Spread evenly", self._spread),
                         ("Each line on its own pallet", self._one_each),
                         ("All on pallet 1", self._all_first)):
            flat_btn(bar, text, fn, bg=CNE, pady=px(4),
                     font=F_SM).pack(side="left", padx=(0, px(6)))
        if add_order is not None:
            flat_btn(bar, "+ Add another order…", self._add, bg=CA,
                     pady=px(4), font=F_SM).pack(side="right")

        wrap = tk.Frame(self, bg=CCA, highlightbackground=CBR,
                        highlightthickness=1)
        wrap.pack(fill="both", expand=True, padx=px(14))
        canvas = tk.Canvas(wrap, bg=CCA, highlightthickness=0)
        xs = ttk.Scrollbar(wrap, orient="horizontal", command=canvas.xview)
        ys = ttk.Scrollbar(wrap, orient="vertical", command=canvas.yview)
        canvas.configure(xscrollcommand=xs.set, yscrollcommand=ys.set)
        xs.pack(side="bottom", fill="x")
        ys.pack(side="right", fill="y")
        canvas.pack(fill="both", expand=True)
        self.grid_frame = tk.Frame(canvas, bg=CCA, padx=px(8), pady=px(6))
        canvas.create_window((0, 0), window=self.grid_frame, anchor="nw")
        self.grid_frame.bind("<Configure>", lambda _e: canvas.configure(
            scrollregion=canvas.bbox("all")))
        self._shown = 0
        self._rebuild()
        self._all_first()

    # ── The orders on these pallets ───────────────────────────────────────

    @property
    def items(self) -> list:
        """Every line of every order, in order: one row of the grid each."""
        return [it for e in self.entries for it in e["items"]]

    @property
    def order(self) -> dict:
        return self.entries[0]["order"]

    def _subtitle(self):
        parts = []
        for e in self.entries:
            who = (e.get("customer") or {}).get("name") or \
                e["order"].get("customer_name", "")
            parts.append(f"O/N {_pallets.order_number(e['order'])}  ·  {who}")
        tail = ("  ·  one sheet per pallet" if len(parts) == 1 else
                f"\n{len(parts)} orders on the same pallets  ·  one sheet "
                "per pallet")
        self.subtitle.config(text="   +   ".join(parts) + tail)

    def add_entry(self, entry) -> bool:
        """Put another order on these pallets. Refused when it is already
        here or goes to a different address."""
        if not entry or not entry.get("items"):
            return False
        on = _pallets.order_number(entry["order"])
        if any(_pallets.order_number(e["order"]) == on and on
               for e in self.entries):
            messagebox.showinfo("Pallet labels",
                                f"O/N {on} is already on these pallets.",
                                parent=self)
            return False
        if not _pallets.same_place(self.entries + [entry]):
            messagebox.showwarning(
                "Pallet labels",
                f"O/N {on} is going to a different address. A pallet goes "
                "to one place - print its pallet labels on their own.",
                parent=self)
            return False
        old = self._grid()
        self.entries.append(entry)
        n = self._n()
        self._shown = 0
        self._rebuild()
        self._fill(old + [[_pallets.ordered(it)] + [0] * (n - 1)
                          for it in entry["items"]])
        return True

    def _add(self):
        try:
            entry = self.add_order(self)
        except Exception as exc:
            messagebox.showerror("Pallet labels", str(exc), parent=self)
            return
        try:
            self.grab_set()   # a picker took the grab - take it back
        except Exception:
            pass
        self.add_entry(entry)

    def _remove(self, idx: int):
        if len(self.entries) < 2:
            return
        old = self._grid()
        start = sum(len(e["items"]) for e in self.entries[:idx])
        stop = start + len(self.entries[idx]["items"])
        del self.entries[idx]
        self._shown = 0
        self._rebuild()
        self._fill(old[:start] + old[stop:])

    def _n(self) -> int:
        try:
            return max(1, min(self.MAX_PALLETS, int(self.count.get())))
        except (TypeError, ValueError):
            return 1

    def _rebuild(self):
        n = self._n()
        if n == self._shown and self.cells:
            return
        self._subtitle()
        old = [[v.get() for v in row] for row in self.cells]
        for w in self.grid_frame.winfo_children():
            w.destroy()
        heads = ["Line", "Ordered"] + [f"Pallet {j + 1}" for j in range(n)] \
            + ["Not on a pallet"]
        for col, text in enumerate(heads):
            tk.Label(self.grid_frame, text=text, bg=CCA, fg=CMU, font=F_SM,
                     anchor="w").grid(row=0, column=col, sticky="w",
                                      padx=px(4), pady=(0, px(4)))
        self.cells, self.left = [], []
        multi = len(self.entries) > 1
        r = 1
        i = 0
        for k, e in enumerate(self.entries):
            if multi:
                head = tk.Frame(self.grid_frame, bg=CCA)
                head.grid(row=r, column=0, columnspan=3 + n, sticky="w",
                          pady=(px(6) if k else 0, px(2)))
                who = (e.get("customer") or {}).get("name") or \
                    e["order"].get("customer_name", "")
                tk.Label(head, text=f"O/N {_pallets.order_number(e['order'])}"
                                    f"  ·  {who}",
                         bg=CCA, fg=CA, font=F_BOLD).pack(side="left")
                FlatButton(head, text="Remove", font=F_SM, bg=CCA, fg=CRD,
                          relief="flat", bd=0, cursor="hand2",
                          activebackground=CCA,
                          command=lambda x=k: self._remove(x)
                          ).pack(side="left", padx=(px(10), 0))
                r += 1
            for item in e["items"]:
                tk.Label(self.grid_frame, text=_pallets.line_text(item),
                         bg=CCA, fg=CTX, font=F_BODY, anchor="w",
                         width=34).grid(row=r, column=0, sticky="w",
                                        padx=px(4), pady=px(1))
                tk.Label(self.grid_frame, text=str(_pallets.ordered(item)),
                         bg=CCA, fg=CTX, font=F_BODY).grid(row=r, column=1,
                                                           padx=px(4))
                row = []
                for j in range(n):
                    prev = old[i][j] if i < len(old) and j < len(old[i]) \
                        else ""
                    var = tk.StringVar(value=prev)
                    var.trace_add("write", lambda *_: self._update_left())
                    field_entry(self.grid_frame, textvariable=var, width=5
                                ).grid(row=r, column=2 + j, padx=px(3),
                                       pady=px(1))
                    row.append(var)
                self.cells.append(row)
                lab = tk.Label(self.grid_frame, text="", bg=CCA, fg=CMU,
                               font=F_SM)
                lab.grid(row=r, column=2 + n, padx=px(6), sticky="w")
                self.left.append(lab)
                r += 1
                i += 1
        self._shown = n
        self._update_left()

    def _grid(self):
        return [[v.get().strip() for v in row] for row in self.cells]

    def _update_left(self):
        for item, row, lab in zip(self.items, self.cells,
                                  getattr(self, "left", [])):
            total = 0
            for v in row:
                try:
                    total += int(v.get() or 0)
                except ValueError:
                    pass
            left = _pallets.ordered(item) - total
            lab.config(text=("all on" if left == 0 else
                             f"{left} left" if left > 0 else
                             f"{-left} too many"),
                       fg=CGR if left == 0 else CRD if left < 0 else CMU)

    def _fill(self, rows):
        for vars_, values in zip(self.cells, rows):
            for v, q in zip(vars_, list(values) + [""] * len(vars_)):
                v.set(str(q) if q not in (0, "0", None) else "")

    def _spread(self):
        n = self._n()
        self._fill([_pallets.spread(_pallets.ordered(it), n)
                    for it in self.items])

    def _one_each(self):
        n = self._n()
        rows = []
        for i, it in enumerate(self.items):
            row = [0] * n
            row[i % n] = _pallets.ordered(it)
            rows.append(row)
        self._fill(rows)

    def _all_first(self):
        n = self._n()
        self._fill([[_pallets.ordered(it)] + [0] * (n - 1)
                    for it in self.items])

    def _print(self):
        try:
            labels, warnings = _pallets.build_orders(self.entries, self._n(),
                                                     self._grid())
        except _pallets.PalletError as exc:
            messagebox.showwarning("Pallet labels",
                                   "Not printed yet:\n\n" + "\n".join(
                                       f"  • {p}" for p in exc.problems),
                                   parent=self)
            return
        if warnings and not messagebox.askyesno(
                "Pallet labels", "\n".join(warnings) + "\n\nPrint anyway?",
                parent=self):
            return
        numbers = [_pallets.order_number(e["order"]) or "order"
                   for e in self.entries]
        safe = re.sub(r"[^A-Za-z0-9_-]+", "_", "+".join(numbers)
                      ).strip("_")[:60] or "order"
        ORDERS_DIR.mkdir(parents=True, exist_ok=True)
        stamp = _dt_module.datetime.now().strftime("%Y%m%d-%H%M%S")
        path = ORDERS_DIR / f"pallet_labels_{safe}_{stamp}.pdf"
        try:
            _pallets.render_pdf(labels, str(path))
        except Exception as exc:
            messagebox.showerror("Pallet labels", f"Could not make them:\n"
                                 f"{exc}", parent=self)
            return
        try:
            _db.log_action("pallet_labels_printed",
                           f"O/N: {', '.join(numbers)} | "
                           f"{len(labels)} pallet"
                           f"{'s' if len(labels) != 1 else ''}")
        except Exception:
            pass
        self.note.config(text=f"Saved {path.name}")
        self.last_path = str(path)
        _open_path(str(path))


class _OrderPicker(tk.Toplevel):
    """Pick one order from a list, with a search box. result = the row."""

    def __init__(self, master, title: str, rows: list):
        super().__init__(master)
        self.title(title)
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.rows = list(rows)
        self.result = None
        _centre_on_parent(self, master, px(620), px(460))
        self.bind("<Escape>", lambda _e: self.destroy())
        top = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text=title, bg=CBG, fg=CTX, font=F_BOLD).pack(anchor="w")
        self.q = tk.StringVar()
        ent = field_entry(top, textvariable=self.q)
        ent.pack(fill="x", pady=(px(6), 0))
        self.q.trace_add("write", lambda *_: self._fill())
        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Cancel", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        flat_btn(foot, "Add", self._pick, bg=CGR,
                 pady=px(6)).pack(side="right", padx=(0, px(8)))
        self.lb = tk.Listbox(self, font=F_BODY, bg=CCA, fg=CTX,
                             selectbackground=CA, selectforeground="white",
                             relief="flat", highlightthickness=1,
                             highlightbackground=CBR, activestyle="none")
        self.lb.pack(fill="both", expand=True, padx=px(14))
        self.lb.bind("<Double-Button-1>", lambda _e: self._pick())
        self.lb.bind("<Return>", lambda _e: self._pick())
        ent.bind("<Return>", lambda _e: self._pick())
        ent.bind("<Down>", lambda _e: (self.lb.focus_set(),
                                       self.lb.selection_set(0)))
        self.shown: list = []
        self._fill()
        self.after(50, ent.focus_set)

    @staticmethod
    def text(row) -> str:
        return "   ·   ".join(p for p in (
            f"O/N {row.get('order_no') or '—'}", row.get("customer") or "",
            f"due {row.get('date_due')}" if row.get("date_due") else "",
            row.get("status") or "") if p)

    def _fill(self):
        q = self.q.get().strip().lower()
        self.shown = [r for r in self.rows if not q or q in self.text(r).lower()]
        self.lb.delete(0, "end")
        for r in self.shown[:300]:
            self.lb.insert("end", "  " + self.text(r))
        if self.shown:
            self.lb.selection_set(0)

    def _pick(self):
        sel = self.lb.curselection()
        if not sel and len(self.shown) == 1:
            sel = (0,)
        if sel:
            self.result = self.shown[sel[0]]
            self.destroy()


class MergeCustomersDialog(tk.Toplevel):
    """Fold accounts that are the same company into one.

    Nothing is merged on a guess. Suggestions say why they were made, every
    field the accounts disagree on is chosen, the counts of what will move
    are shown, and the merge is confirmed in words before it runs. It can be
    undone from here afterwards.
    """

    def __init__(self, master, on_done=None):
        super().__init__(master)
        self.title("Merge customer accounts")
        self.transient(master)
        self.grab_set()
        self.configure(bg=CBG)
        self.on_done = on_done
        _centre_on_parent(self, master, px(1060), px(720))
        self.bind("<Escape>", lambda _e: self.destroy())
        self.request_id = _merge.new_request_id()
        try:
            self.people = _db.get_customers(active_only=True)
        except Exception:
            self.people = []
        self.by_id = {c["id"]: c for c in self.people if c.get("id")}
        self.chosen: list = []
        self.field_vars: dict = {}
        self.price_vars: dict = {}
        self.prices: list = []

        top = tk.Frame(self, bg=CA, padx=px(16), pady=px(10))
        top.pack(fill="x")
        tk.Label(top, text="Merge customer accounts", bg=CA, fg="white",
                 font=(FAM, 13, "bold")).pack(anchor="w")
        tk.Label(top, text="For one company entered twice. Different branches "
                           "of a company stay separate accounts.",
                 bg=CA, fg="white", font=F_SM).pack(anchor="w")

        foot = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        foot.pack(fill="x", side="bottom")
        flat_btn(foot, "Close", self.destroy, bg=CNE,
                 pady=px(6)).pack(side="right")
        self.merge_btn = flat_btn(foot, "Merge…", self._merge, bg=CRD,
                                  pady=px(6))
        self.merge_btn.pack(side="right", padx=(0, px(8)))
        flat_btn(foot, "Undo a merge…", self._undo, bg=CNE,
                 pady=px(6)).pack(side="left")

        body = tk.Frame(self, bg=CBG, padx=px(14), pady=px(10))
        body.pack(fill="both", expand=True)
        left = tk.Frame(body, bg=CBG)
        left.pack(side="left", fill="y")
        self.search = tk.StringVar()
        tk.Label(left, text="Find an account", bg=CBG, fg=CMU,
                 font=F_SM).pack(anchor="w")
        field_entry(left, textvariable=self.search, width=34).pack(fill="x")
        self.search.trace_add("write", lambda *_: self._fill_list())
        self.listing = ttk.Treeview(left, columns=("name", "where"),
                                    show="headings", height=12,
                                    style="TAF.Treeview", selectmode="extended")
        self.listing.heading("name", text="Account", anchor="w")
        self.listing.heading("where", text="Delivers to", anchor="w")
        self.listing.column("name", width=px(200))
        self.listing.column("where", width=px(140))
        self.listing.pack(fill="y", expand=True, pady=(px(6), 0))
        flat_btn(left, "Compare the selected accounts", self._use_selection,
                 bg=CA, pady=px(5)).pack(fill="x", pady=(px(6), 0))
        tk.Label(left, text="Suggested (check before merging):", bg=CBG,
                 fg=CMU, font=F_SM).pack(anchor="w", pady=(px(10), 0))
        self.suggest = tk.Listbox(left, height=6, font=F_SM, bg=CCA,
                                  relief="flat", highlightthickness=0)
        self.suggest.pack(fill="x")
        self.suggest.bind("<<ListboxSelect>>", self._use_suggestion)
        self._groups = _merge.suggest_duplicates(self.people)
        for g in self._groups:
            names = " + ".join(a.get("name", "") for a in g["accounts"])
            self.suggest.insert("end", f"{names}  ({'; '.join(g['reasons'])})"
                                + ("  ⚠ different ABNs" if g["abn_conflict"]
                                   else ""))

        self.right = tk.Frame(body, bg=CCA, highlightbackground=CBR,
                              highlightthickness=1, padx=px(12), pady=px(10))
        self.right.pack(side="left", fill="both", expand=True,
                        padx=(px(12), 0))
        self._fill_list()
        self._draw_compare()

    def _fill_list(self):
        q = self.search.get().strip().lower()
        for iid in self.listing.get_children():
            self.listing.delete(iid)
        for c in self.people:
            text = " ".join(str(c.get(k) or "") for k in (
                "name", "short_name", "legal_name", "delivery_city",
                "phone", "email")).lower()
            if q and q not in text:
                continue
            self.listing.insert("", "end", iid=c["id"], values=(
                c.get("name", ""), c.get("delivery_city", "")))

    def _use_selection(self):
        ids = list(self.listing.selection())
        if len(ids) < 2:
            messagebox.showinfo("Merge", "Choose two or more accounts "
                                "(hold Ctrl to choose more than one).",
                                parent=self)
            return
        self.chosen = ids
        self._draw_compare()

    def _use_suggestion(self, _e=None):
        sel = self.suggest.curselection()
        if not sel:
            return
        self.chosen = list(self._groups[sel[0]]["ids"])
        self._draw_compare()

    def _draw_compare(self):
        for w in self.right.winfo_children():
            w.destroy()
        self.field_vars, self.price_vars = {}, {}
        if len(self.chosen) < 2:
            tk.Label(self.right, text="Choose the accounts to compare, from "
                                      "the list or a suggestion.", bg=CCA,
                     fg=CMU, font=F_BODY).pack(anchor="w")
            return
        accounts = [self.by_id[i] for i in self.chosen if i in self.by_id]
        self.survivor = tk.StringVar(value=accounts[0]["id"])
        tk.Label(self.right, text="The account that stays", bg=CCA, fg=CTX,
                 font=F_BOLD).pack(anchor="w")
        try:
            counts = {r["id"]: r for r in _merge.preview(self.chosen)}
        except Exception:
            counts = {}
        for a in accounts:
            n = counts.get(a["id"], {})
            tk.Radiobutton(
                self.right, variable=self.survivor, value=a["id"],
                text=f"{a.get('name','')}  —  {n.get('orders', '?')} orders, "
                     f"{n.get('quotes', '?')} quotes, "
                     f"{n.get('customer_prices', '?')} agreed prices, "
                     f"{n.get('sites', 0)} sites",
                bg=CCA, fg=CTX, font=F_BODY, activebackground=CCA,
                selectcolor=CBG, anchor="w").pack(fill="x")
        grid = tk.Frame(self.right, bg=CCA)
        grid.pack(fill="x", pady=(px(10), 0))
        conflicts = _merge.conflicts(accounts)
        names = [str(a.get("name") or "") for a in accounts]
        self.name_var = tk.StringVar(value=names[0])
        tk.Label(grid, text="Company name to keep", bg=CCA, fg=CMU,
                 font=F_SM).grid(row=0, column=0, sticky="w")
        ttk.Combobox(grid, textvariable=self.name_var, values=names,
                     width=46).grid(row=0, column=1, sticky="w")
        r = 1
        for field, values in conflicts.items():
            if field == "name":
                continue
            var = tk.StringVar(value="")
            self.field_vars[field] = var
            tk.Label(grid, text=field.replace("_", " ").capitalize(),
                     bg=CCA, fg=CMU, font=F_SM).grid(row=r, column=0,
                                                     sticky="w")
            ttk.Combobox(grid, textvariable=var, values=values,
                         state="readonly", width=46).grid(row=r, column=1,
                                                          sticky="w")
            r += 1
        self.abn_ok = tk.BooleanVar(value=False)
        if _merge.abn_conflict(accounts):
            tk.Checkbutton(self.right, variable=self.abn_ok, bg=CCA, fg=CRD,
                           font=F_BOLD, activebackground=CCA, selectcolor=CBG,
                           text="These have different ABNs. I have checked "
                                "they are the same company."
                           ).pack(anchor="w", pady=(px(6), 0))
        try:
            self.prices = (_db.get_client().table("customer_prices")
                           .select("customer_id,part_number,unit_price,"
                                   "discount").in_("customer_id", self.chosen)
                           .execute().data or [])
        except Exception:
            self.prices = []
        # Any part priced on two or more of the chosen accounts, whichever
        # of them ends up staying.
        for part in _merge.price_conflicts(self.prices, self.chosen[0],
                                           self.chosen[1:]):
            var = tk.StringVar(value="")
            self.price_vars[part] = var
            opts = []
            for p in self.prices:
                if str(p.get("part_number") or "").strip().upper() == part:
                    who = self.by_id.get(p["customer_id"], {}).get("name", "")
                    opts.append(f"{who}: {p.get('unit_price') or ''}"
                                f"{' ' + str(p.get('discount')) + '% off' if p.get('discount') else ''}"
                                f"  [{p['customer_id']}]")
            tk.Label(grid, text=f"Agreed price {part or '(discount)'}",
                     bg=CCA, fg=CMU, font=F_SM).grid(row=r, column=0,
                                                     sticky="w")
            ttk.Combobox(grid, textvariable=var, values=opts,
                         state="readonly", width=46).grid(row=r, column=1,
                                                          sticky="w")
            r += 1
        notes = _merge.external_ids(accounts, self.name_var.get())
        if notes:
            tk.Label(self.right, text="Left to tidy outside the program:\n"
                     + "\n".join("• " + n for n in notes), bg=CCA, fg=CMU,
                     font=F_SM, justify="left", wraplength=px(620)
                     ).pack(anchor="w", pady=(px(10), 0))

    def _decided(self):
        accounts = [self.by_id[i] for i in self.chosen if i in self.by_id]
        survivor = self.survivor.get()
        chosen = {"name": self.name_var.get().strip()}
        for field, var in self.field_vars.items():
            if var.get():
                chosen[field] = var.get()
        prices = {}
        for part, var in self.price_vars.items():
            m = re.search(r"\[([0-9a-f-]+)\]$", var.get())
            if m:
                prices[part] = "survivor" if m.group(1) == survivor \
                    else m.group(1)
        todo = _merge.check_ready(accounts, survivor, chosen, prices,
                                  self.prices, self.abn_ok.get())
        return accounts, survivor, chosen, prices, todo

    def _merge(self):
        if not _db.can_merge_customers():
            messagebox.showinfo("Merge", "Only a manager can merge accounts.",
                                parent=self)
            return
        if len(self.chosen) < 2:
            messagebox.showinfo("Merge", "Choose the accounts first.",
                                parent=self)
            return
        accounts, survivor, chosen, prices, todo = self._decided()
        if todo:
            messagebox.showwarning("Still to decide", "\n".join(
                "• " + t for t in todo), parent=self)
            return
        gone = [a for a in accounts if a["id"] != survivor]
        keep = self.by_id[survivor]
        summary = (f"Keep \"{keep.get('name')}\" as \"{chosen['name']}\", and "
                   f"merge into it:\n\n" + "\n".join(
                       f"  • {a.get('name')}" for a in gone) +
                   "\n\nTheir orders, quotes, sites, returns, recurring jobs "
                   "and agreed prices move to it. The merged accounts are "
                   "archived, not deleted, and their names still find it.\n\n"
                   "Merge now?")
        if not messagebox.askyesno("Merge customer accounts", summary,
                                   icon="warning", parent=self):
            return
        expected = {a["id"]: a.get("updated_at") for a in accounts
                    if a.get("updated_at")}
        decided = _merge.decisions(keep, chosen, prices,
                                   bool(self.abn_ok.get()))
        try:
            merge_id = _merge.merge(self.request_id, survivor,
                                    [a["id"] for a in gone], decided,
                                    expected or None)
        except Exception as exc:
            messagebox.showerror("Merge", f"Nothing was merged:\n{exc}",
                                 parent=self)
            return
        try:
            _db.log_action("customers_merged",
                           f"Into: {chosen['name']} | From: " +
                           ", ".join(a.get("name", "") for a in gone) +
                           f" | Merge {merge_id}")
        except Exception:
            pass
        # The account's name onto every past order and quote of it - in the
        # list and inside the order, which View Order and reprints read.
        try:
            n = _merge.sync_order_names(survivor)
            names = (_merge.STEP_36 if n is None else
                     f"{n} past order{'s' if n != 1 else ''} now show "
                     f"\"{chosen['name']}\".")
        except Exception as exc:
            names = f"Their past orders still show the old names: {exc}"
        messagebox.showinfo("Merged", "Done. " + names + "\n\nIt can be "
                            "undone from \"Undo a merge…\" if it was wrong.",
                            parent=self)
        self.request_id = _merge.new_request_id()
        if self.on_done:
            self.on_done()
        self.destroy()

    def _undo(self):
        try:
            merges = [m for m in _merge.recent_merges() if not m.get("undone_at")]
        except Exception as exc:
            messagebox.showerror("Undo", str(exc), parent=self)
            return
        if not merges:
            messagebox.showinfo("Undo", "There are no merges to undo.",
                                parent=self)
            return
        lines = [f"{i + 1}. {m.get('merged_at','')[:16]}  by "
                 f"{m.get('merged_by_name') or '—'}  →  "
                 f"{((m.get('decisions') or {}).get('set') or {}).get('name', '')}"
                 for i, m in enumerate(merges[:10])]
        pick = simpledialog.askinteger(
            "Undo a merge", "\n".join(lines) + "\n\nWhich one?", parent=self,
            minvalue=1, maxvalue=len(lines))
        if not pick:
            return
        try:
            out = _merge.undo(merges[pick - 1]["id"])
        except Exception as exc:
            messagebox.showerror("Undo", f"Not undone:\n{exc}", parent=self)
            return
        skipped = out.get("skipped") or []
        # Each account back on its own orders, under its own name.
        undone = merges[pick - 1]
        for cid in [undone.get("survivor_id")] + list(
                undone.get("merged_ids") or []):
            if cid:
                try:
                    _merge.sync_order_names(cid)
                except Exception:
                    pass
        messagebox.showinfo("Undo", "Undone." + (
            f"\n\n{len(skipped)} record(s) had been changed since the merge "
            "and were left as they are now." if skipped else ""), parent=self)
        if self.on_done:
            self.on_done()
        self.destroy()


# The pause between building one background tab and the next: room for the
# window to answer a click or a key between them.
PREBUILD_GAP_MS = 120


class ModernOrderApp(tk.Frame):

    def __init__(self, master):
        super().__init__(master, bg=CBG)
        self.master = master
        _install_dropdown_rules(master)
        _install_ui_pump(master.winfo_toplevel())
        # Anchor order storage to APP_DIR (never cwd — see OrderService).
        # This also aligns saved order JSONs with ORDERS_DIR, where the
        # Previous Orders local scan looks for them.
        self.service = OrderService(APP_DIR)
        self.items: list = []
        self._all_orders_data: list = []
        self._ticked: set = set()     # orders ticked in Previous Orders
        self._tab_frames: dict = {}
        self._tab_buttons: dict = {}
        self._tab_loaded: dict = {}   # tab -> monotonic time of last data load (freshness cache)

        # Load persisted settings
        self._settings = _load_settings()
        self._custom_media: list = list(self._settings.get("custom_media_types", []))
        self._custom_filter_types: list = list(
            self._settings.get("custom_filter_types", []))
        # {media name: part-number code} — Carbon -> CARB, so a flat panel
        # comes out as FPFCARB25-020.
        self._media_codes: dict = dict(self._settings.get("media_codes", {}))
        # Presets/filter types come from the shared catalogue; start from the
        # last-known local copy so a slow or offline start still has them.
        _load_catalog_cache()

        self._draft_save_id        = None   # debounce handle for auto-save
        self._tooltip_win          = None   # hover tooltip window ref
        self._selected_customer_id = ""    # customer_id of currently-picked customer
        self._selected_customer_name = ""  # the name it was linked under
        self._customer_records: list = []  # full customer dicts for autocomplete
        self._inactive_banner      = None  # inactive-customer banner widget

        _configure_ttk_style()
        self._build_ui()
        self._bind_shortcuts()
        self._refresh_items_tree()

        # Offer to restore any unsaved draft (after UI is fully built)
        self.master.after(600, self._check_restore_draft)

        # Push any orders queued while offline, then re-check every 5 minutes
        self.master.after(3000, self._start_pending_sync_loop)

        # Collect and read any purchase-order photos sent from a phone
        self.master.after(5000, self._start_phone_inbox_loop)

        # Pull the shared catalogue (presets + custom filter types)
        self.master.after(200, self._refresh_catalog_from_db)

        # First launch after an update → show that version's release notes once
        self.master.after(1500, self._maybe_show_whats_new)

        # Clean up any leftover _old.exe from a previous auto-update
        try:
            from taf_order_app.updater import cleanup_old_exe
            cleanup_old_exe()
        except Exception:
            pass

        # Excel and Word are no longer started here. Worksheets and bag
        # sheets are drawn straight to PDF; Word is only a fallback, started
        # if it is ever needed. Starting both hidden on every launch slowed
        # the whole PC down for nothing.
        threading.Thread(target=self._bg_check_update, daemon=True).start()

    def _bg_check_update(self):
        """Background update check — runs once after login."""
        import queue as _q
        q = _q.Queue()
        try:
            from taf_order_app.updater import check_for_update
            info = check_for_update()
            q.put(info)
        except Exception:
            q.put(None)

        def _handle():
            try:
                info = q.get_nowait()
                if info:
                    self._show_update_banner(info)
            except Exception:
                pass
        self.master.after(500, _handle)

    def _show_update_banner(self, info: dict):
        """Show a prominent update notification popup over the app."""
        # Avoid showing multiple banners
        if getattr(self, "_update_banner_shown", False):
            return
        self._update_banner_shown = True

        v     = info.get("version", "")
        notes = info.get("release_notes", "")

        # ── Outer overlay strip ───────────────────────────────────────────
        banner = tk.Frame(self, bg="#145A32", padx=0, pady=0)
        banner.place(relx=0, rely=0, relwidth=1, anchor="nw")

        inner = tk.Frame(banner, bg="#145A32", padx=18, pady=10)
        inner.pack(fill="x")

        # Left: icon + text
        left = tk.Frame(inner, bg="#145A32")
        left.pack(side="left", fill="y")

        tk.Label(left, text="UPDATE AVAILABLE",
                 bg="#145A32", fg="#A9DFBF",
                 font=(FAM, 7, "bold"), anchor="w").pack(anchor="w")

        tk.Label(left, text=f"Version {v} is ready to install",
                 bg="#145A32", fg="white",
                 font=(FAM, 11, "bold"), anchor="w").pack(anchor="w")

        # Show first line of notes inline; "Read More" if there's more
        note_lines = [l.strip() for l in notes.splitlines() if l.strip()] if notes else []
        if note_lines:
            preview = note_lines[0]
            if len(preview) > 80:
                preview = preview[:77] + "…"
            note_row = tk.Frame(left, bg="#145A32")
            note_row.pack(anchor="w")
            tk.Label(note_row, text=preview,
                     bg="#145A32", fg="#A9DFBF",
                     font=(FAM, 9), anchor="w").pack(side="left")
            if len(note_lines) > 1 or len(notes.strip()) > 80:
                def _show_notes():
                    popup = tk.Toplevel(self)
                    popup.title(f"What's new in v{v}")
                    popup.configure(bg="#1B2631")
                    popup.resizable(False, False)
                    popup.grab_set()
                    pw, ph = 520, 360
                    sx = self.winfo_rootx() + (self.winfo_width()  - pw) // 2
                    sy = self.winfo_rooty() + (self.winfo_height() - ph) // 2
                    popup.geometry(f"{pw}x{ph}+{sx}+{sy}")
                    tk.Label(popup, text=f"What's new in v{v}",
                             bg="#1B2631", fg="white",
                             font=(FAM, 13, "bold")).pack(anchor="w", padx=20, pady=(16, 6))
                    txt_frame = tk.Frame(popup, bg="#1B2631")
                    txt_frame.pack(fill="both", expand=True, padx=20, pady=(0, 10))
                    txt = tk.Text(txt_frame, bg="#212F3D", fg="#D5DBDB",
                                  font=(FAM, 10), relief="flat",
                                  wrap="word", padx=12, pady=10,
                                  state="normal", cursor="arrow",
                                  highlightthickness=0)
                    txt.insert("1.0", notes)
                    txt.config(state="disabled")
                    vsb = ttk.Scrollbar(txt_frame, command=txt.yview)
                    txt.configure(yscrollcommand=vsb.set)
                    vsb.pack(side="right", fill="y")
                    txt.pack(side="left", fill="both", expand=True)
                    FlatButton(popup, text="Close", command=popup.destroy,
                              bg="#27AE60", fg="white",
                              activebackground="#1E8449", activeforeground="white",
                              relief="flat", bd=0,
                              font=(FAM, 10, "bold"),
                              padx=20, pady=8, cursor="hand2").pack(pady=(0, 16))
                FlatButton(note_row, text="Read more ›",
                          command=_show_notes,
                          bg="#145A32", fg="#A9DFBF",
                          activebackground="#0E3D22", activeforeground="white",
                          relief="flat", bd=0,
                          font=(FAM, 9, "underline"),
                          padx=6, cursor="hand2").pack(side="left")

        # Right: buttons
        right = tk.Frame(inner, bg="#145A32")
        right.pack(side="right", fill="y")

        def _update_now():
            banner.destroy()
            self._update_banner_shown = False
            self._do_update(info)

        def _dismiss():
            banner.destroy()
            self._update_banner_shown = False

        FlatButton(right, text="UPDATE NOW",
                  command=_update_now,
                  bg="#27AE60", fg="white",
                  activebackground="#1E8449", activeforeground="white",
                  relief="flat", bd=0,
                  font=(FAM, 10, "bold"),
                  padx=20, pady=8, cursor="hand2").pack(side="left", padx=(0, 10))

        FlatButton(right, text="Later",
                  command=_dismiss,
                  bg="#145A32", fg="#A9DFBF",
                  activebackground="#0E3D22", activeforeground="white",
                  relief="flat", bd=0,
                  font=(FAM, 9),
                  padx=10, pady=8, cursor="hand2").pack(side="left")

    def _do_update(self, info: dict):
        from taf_order_app.updater import download_and_install
        import queue as _q

        if not info.get("download_url"):
            messagebox.showinfo("Update Available",
                f"Version {info.get('version','')} is available but no download link has been set yet.\n\n"
                "Ask your administrator to upload the new installer.")
            return

        if not getattr(sys, "frozen", False):
            messagebox.showinfo("Update",
                "Auto-update only works in the installed app.\n"
                "Download the latest version from the GitHub Releases page.")
            return

        dlg = tk.Toplevel(self.master)
        dlg.title("Updating…")
        dlg.resizable(False, False)
        dlg.transient(self.master)
        dlg.grab_set()
        dlg.configure(bg=CBG)

        tk.Label(dlg, text="Downloading update…",
                 bg=CBG, fg=CA, font=F_TTL, padx=24, pady=14).pack()

        status_var = tk.StringVar(value="Connecting…")
        tk.Label(dlg, textvariable=status_var,
                 bg=CBG, fg=CTX, font=F_BODY, padx=24).pack()

        bar = ttk.Progressbar(dlg, length=340, mode="determinate", maximum=100)
        bar.pack(padx=24, pady=(8, 20))

        dlg.update_idletasks()
        W, H = 400, 150
        dlg.geometry(f"{W}x{H}+{self.master.winfo_rootx() + self.master.winfo_width()//2 - W//2}"
                     f"+{self.master.winfo_rooty() + self.master.winfo_height()//2 - H//2}")

        q = _q.Queue()

        def _progress(pct, msg):
            q.put((pct, msg))

        def _work():
            try:
                download_and_install(info, progress_cb=_progress)
            except Exception as exc:
                q.put((-1, str(exc)))

        def _poll():
            try:
                while True:
                    pct, msg = q.get_nowait()
                    if pct == -1:
                        dlg.destroy()
                        messagebox.showerror("Update Failed", msg)
                        return
                    bar["value"] = pct
                    status_var.set(msg)
                    dlg.update_idletasks()
                    if pct >= 100:
                        # Give the PS1 script 1.5s to launch, then hard-exit
                        dlg.after(1500, lambda: os._exit(0))
                        return
            except _q.Empty:
                pass
            dlg.after(100, _poll)

        threading.Thread(target=_work, daemon=True).start()
        dlg.after(100, _poll)

    def _sign_out(self):
        if not messagebox.askyesno("Sign Out", "Sign out and return to the login screen?"):
            return
        _db.flush_audit_log(3)        # written while still signed in
        _db.sign_out()
        self.master.destroy()
        _start_app()

    def _check_update_manual(self):
        from taf_order_app.updater import latest_release, UpdateCheckError
        import queue as _q

        # Guard against re-entrancy. We keep the button ENABLED and just change
        # its label — the disabled pill renders light-on-light and looked like
        # the button had vanished. (No self.update() here either — calling it
        # inside a click handler is a re-entrancy hazard.)
        if getattr(self, "_upd_checking", False):
            return
        self._upd_checking = True
        self._check_upd_btn.config(text="Checking…")
        self._upd_status_var.set("Checking for updates…")
        q = _q.Queue()

        def _work():
            # One request, not two: the check used to ask GitHub twice per
            # click, which doubled how fast an office connection ran into
            # GitHub's 60-an-hour limit for the answer it already had.
            try:
                q.put(("ok", latest_release()))
            except UpdateCheckError as exc:
                q.put(("error", str(exc)))
            except Exception as exc:
                q.put(("error", str(exc) or exc.__class__.__name__))

        def _poll():
            try:
                kind, data = q.get_nowait()
            except _q.Empty:
                self.master.after(150, _poll)
                return
            # Whatever happened, always restore the button so it can't get
            # stuck / invisible.
            self._upd_checking = False
            self._check_upd_btn.config(state="normal", text="Check for Updates")
            if kind == "ok":
                info = data
                v = info.get("version", "")
                if info.get("is_newer"):
                    self._upd_status_var.set(f"v{v} is available.")
                    self._pending_update = info
                    self._install_upd_btn.pack(side="left", padx=(8, 0))
                    self._update_banner_shown = False   # allow re-show
                    self._show_update_banner(info)
                    self._download_upd_btn.pack_forget()
                else:
                    # Only said when GitHub actually answered the question.
                    self._upd_status_var.set(
                        f"You're up to date. This PC is on v{APP_VERSION}, "
                        f"and the newest release is v{v}.")
                    self._install_upd_btn.pack_forget()
                    self._download_upd_btn.pack_forget()
            else:
                # A failed check is NOT "up to date" — saying so would leave
                # someone on an old build sure they were on the newest one.
                self._upd_status_var.set(
                    f"Couldn't check for updates — {data}. "
                    f"This PC is on v{APP_VERSION}.")
                self._install_upd_btn.pack_forget()
                self._download_upd_btn.pack(side="left", padx=(8, 0))

        threading.Thread(target=_work, daemon=True).start()
        self.master.after(150, _poll)

    def _open_releases_page(self):
        """Open the Releases page so the installer can be downloaded by hand."""
        import webbrowser
        from taf_order_app.updater import RELEASES_PAGE
        try:
            webbrowser.open(RELEASES_PAGE)
            self.status_var.set("Opened the Releases page in your browser.")
        except Exception:
            messagebox.showinfo(
                "Download the Update",
                "Open this page in a browser and download "
                f"TAFOrderEntry_Setup.exe:\n\n{RELEASES_PAGE}")

    def _open_user_management(self):
        from taf_order_app.user_management import UserManagementDialog
        UserManagementDialog(self.master)

    @property
    def all_media_types(self) -> list:
        """Default built-in types followed by any user-added custom types."""
        seen = set(DEFAULT_MEDIA_TYPES)
        custom = [m for m in self._custom_media if m not in seen]
        return DEFAULT_MEDIA_TYPES + custom

    @property
    def all_filter_types(self) -> list:
        """Built-in filter types followed by any user-added custom ones."""
        seen = set(VALID_FILTER_TYPES)
        custom = [f for f in getattr(self, "_custom_filter_types", [])
                  if f not in seen]
        return list(VALID_FILTER_TYPES) + custom

    # ── Top-level layout ──────────────────────────────────────────────────

    def _build_ui(self):
        self.pack(fill="both", expand=True)
        self.master.rowconfigure(0, weight=1)
        self.master.columnconfigure(0, weight=1)

        self._build_header()
        self._build_tab_bar()

        # Content area – both tab frames sit at grid(0,0); tkraise() switches visibility
        self.content = tk.Frame(self, bg=CBG)
        self.content.pack(fill="both", expand=True)
        self.content.rowconfigure(0, weight=1)
        self.content.columnconfigure(0, weight=1)

        # Build the landing tab + status bar now so "home" paints immediately.
        # The other tabs are constructed lazily — a cold start shouldn't be
        # blocked building screens (and their date pickers / babel locale data)
        # the user hasn't opened yet. They warm up during idle time below, and
        # _show_tab builds any tab on demand if it's clicked first.
        self._lazy_tab_builders = {
            "new_order":   self._build_new_order_tab,
            "prev_orders": self._build_prev_orders_tab,
            "delivery":    self._build_delivery_tab,
            "quotes":      self._build_quotes_tab,
            "products":    self._build_products_tab,
            "customers":   self._build_customers_tab,
            "stock":       self._build_stock_tab,
            "supplies":    self._build_supplies_tab,
            "audit_log":   self._build_audit_log_tab,
            "settings":    self._build_settings_tab,
        }
        self._build_dashboard_tab()
        self._build_status_bar()

        # Land on the Dashboard: what's due and what's low is the first thing
        # worth seeing, and it's the leftmost tab.
        self._show_tab("dashboard")

        # Warm the remaining tabs so later switches are instant - starting
        # once the window is up and drawn, one tab at a time with a pause
        # between, so a click in the first few seconds is answered at once
        # instead of waiting for every screen to be built back to back.
        self.master.after(800, self._prebuild_next_tab)

    def _ensure_tab_built(self, key: str):
        """Construct a tab's widgets on first access (lazy building)."""
        builder = getattr(self, "_lazy_tab_builders", {}).pop(key, None)
        if builder is None:
            return
        builder()
        # Every tab is gridded into the same cell and the one you see is
        # whichever is on top. Gridding puts a frame on top — so a tab built
        # quietly in the background covers the one being looked at, and you
        # sign in to the Dashboard and get Settings, because Settings is the
        # last one the prebuilder gets to.
        active = getattr(self, "_active_tab", None)
        if active and active != key and active in self._tab_frames:
            self._tab_frames[active].tkraise()

    def _prebuild_next_tab(self):  # noqa: D401 - see PREBUILD_GAP_MS
        """Build one not-yet-built tab per idle tick, then reschedule."""
        builders = getattr(self, "_lazy_tab_builders", None)
        if not builders:
            return
        self._ensure_tab_built(next(iter(builders)))
        self.master.after(PREBUILD_GAP_MS, self._prebuild_next_tab)

    # ── Header bar ────────────────────────────────────────────────────────

    def _avatar(self, parent, initials, size=34, url=None):
        """The account's photo, or its initials when there isn't one.

        Cropped to a square and masked to a circle here rather than asking
        whoever uploads it to crop it first — a photo straight off a phone is
        the wrong shape, and refusing it would just mean nobody bothers.

        The initials are drawn at once and the photo put over them when it
        arrives: downloading it on the window's own thread held the whole
        app up for as long as the internet took, at every start.
        """
        size = px(size)
        c = tk.Canvas(parent, width=size, height=size, bg=CCA,
                      highlightthickness=0)
        c.create_oval(1, 1, size - 1, size - 1, fill=CA, outline="")
        c.create_text(size // 2, size // 2 + 1, text=initials, fill="white",
                      font=(FAM, int(size * 0.36), "bold"))
        if url:
            cache = self.__dict__.setdefault("_avatar_cache", {})
            photo = cache.get((url, size))
            if photo is not None:
                self._show_avatar(c, photo, size)
            else:
                self._fetch_avatar(url, size, c)
        return c

    @staticmethod
    def _show_avatar(canvas, photo, size) -> None:
        try:
            canvas.delete("all")
            canvas.create_image(size // 2, size // 2, image=photo)
            canvas._photo = photo        # Tk drops an image with no reference
        except tk.TclError:
            pass                         # the header was rebuilt meanwhile

    def _fetch_avatar(self, url: str, size: int, canvas) -> None:
        """Get the photo off the main thread - from disk if it has been
        fetched before, else the internet - then show it."""
        import hashlib
        folder = APP_DIR / "cache"
        disk = folder / f"avatar_{hashlib.sha1(url.encode()).hexdigest()}"

        def _work():
            raw = None
            try:
                if disk.exists():
                    raw = disk.read_bytes()
                else:
                    import urllib.request
                    with urllib.request.urlopen(url, timeout=6) as resp:
                        raw = resp.read()
                    try:
                        folder.mkdir(parents=True, exist_ok=True)
                        disk.write_bytes(raw)
                    except Exception:
                        pass
            except Exception:
                raw = None             # offline, or not reachable: initials
            if raw:
                self.master.after(0, lambda: _apply(raw))

        def _apply(raw):
            photo = self._avatar_image(raw, size)
            self.__dict__.setdefault("_avatar_cache", {})[(url, size)] = photo
            if photo is not None:
                self._show_avatar(canvas, photo, size)

        threading.Thread(target=_work, daemon=True).start()

    @staticmethod
    def _avatar_image(raw: bytes, size: int):
        """Crop and round a profile picture. None if it is not an image."""
        try:
            from PIL import Image, ImageDraw, ImageTk
            import io
            src = Image.open(io.BytesIO(raw)).convert("RGBA")
            # Square from the middle, then scale — never squash a face.
            edge = min(src.size)
            left = (src.width - edge) // 2
            top = (src.height - edge) // 2
            src = src.crop((left, top, left + edge, top + edge))
            src = src.resize((size, size), Image.LANCZOS)
            mask = Image.new("L", (size * 4, size * 4), 0)
            ImageDraw.Draw(mask).ellipse((0, 0, size * 4 - 1, size * 4 - 1),
                                         fill=255)
            src.putalpha(mask.resize((size, size), Image.LANCZOS))
            return ImageTk.PhotoImage(src)
        except Exception:
            return None

    def _account_menu(self):
        """The account, and the screens that keep the app running.

        Products, Settings and user management are set-up work, not the job —
        having them as tabs put them in front of everyone all day. They live
        behind the name instead, which is where people already look for
        their account.
        """
        can_manage = _db.is_ready() and _db.can_manage_prices()
        items = [("Change my picture…", self._change_avatar)]
        if _db.is_ready() and _db.current_avatar_url():
            items.append(("Remove my picture", self._remove_avatar))
        items += [
            ("Change my password…", self._do_change_password),
            None,
            ("Open on a phone…",    self._web_app_link),
            None,
            ("Testable Features", self._testable_features()),
            None,
            ("Products and prices", lambda: self._show_tab("products")),
            ("Settings",            lambda: self._show_tab("settings")),
        ]
        if _db.is_ready() and _db.can_manage_roles():
            pending = 0
            try:
                pending = _db.pending_staff_count()
            except Exception:
                pending = 0
            label = "Staff and accounts"
            if pending:
                label += f"   ({pending} waiting)"
            items.append((label, self._open_user_management))
        items += [None, ("Sign out", self._sign_out)]
        if not can_manage:
            items = [i for i in items
                     if i is None or i[0] != "Products and prices"]

        menu = tk.Menu(self.master, tearoff=0, bg=CCA, fg=CTX,
                       activebackground=CA, activeforeground="white",
                       font=F_BODY, bd=0, relief="flat", activeborderwidth=0)
        for entry in items:
            if entry is None:
                menu.add_separator()
                continue
            label, command = entry
            # A list rather than a callable is a submenu. Everything new goes
            # in one, so the account menu does not grow a line every time a
            # feature is switched on.
            if isinstance(command, list):
                sub = tk.Menu(menu, tearoff=0, bg=CCA, fg=CTX,
                              activebackground=CA, activeforeground="white",
                              font=F_BODY, bd=0, relief="flat",
                              activeborderwidth=0)
                for kid in command:
                    if kid is None:
                        sub.add_separator()
                        continue
                    kid_label, kid_cmd, enabled = kid
                    sub.add_command(label=f"  {kid_label}  ", command=kid_cmd,
                                    state="normal" if enabled else "disabled")
                menu.add_cascade(label=f"  {label}  ", menu=sub)
                continue
            menu.add_command(label=f"  {label}  ", command=command)
        anchor = getattr(self, "_profile_anchor", None)
        try:
            if anchor is not None:
                menu.tk_popup(anchor.winfo_rootx(),
                              anchor.winfo_rooty() + anchor.winfo_height() + px(4))
            else:
                menu.tk_popup(self.master.winfo_pointerx(),
                              self.master.winfo_pointery())
        finally:
            menu.grab_release()

    def _change_avatar(self):
        """Pick a photo for this account."""
        if not (_db.is_ready() and _db.current_user()):
            messagebox.showinfo("Profile picture", "Sign in first.")
            return
        path = filedialog.askopenfilename(
            title="Choose a profile picture",
            filetypes=[("Images", "*.png *.jpg *.jpeg *.webp"),
                       ("All files", "*.*")])
        if not path:
            return
        try:
            size = Path(path).stat().st_size
        except OSError:
            size = 0
        if size > 8 * 1024 * 1024:
            messagebox.showwarning(
                "Profile picture",
                "That picture is over 8MB. Something straight off a phone is "
                "usually plenty — try a smaller one.")
            return
        self.status_var.set("Uploading your picture…")
        self.master.update_idletasks()
        try:
            user_id = str(_db.current_user().id)
            url = _db.upload_avatar(user_id, path)
            _db.set_avatar(user_id, url)
            _db.refresh_current_profile()
        except Exception as exc:
            messagebox.showerror(
                "Profile picture",
                f"That didn't upload:\\n{exc}\\n\\n"
                "If this is the first one, an admin needs to run "
                "migrate_avatars.sql in the Supabase SQL Editor.")
            self.status_var.set("")
            return
        # A new URL each time, so the cache holds the picture, not the old one.
        self._rebuild_header()
        self.status_var.set("Profile picture updated.")

    def _remove_avatar(self):
        if not messagebox.askyesno("Profile picture",
                                   "Remove your picture and go back to your "
                                   "initials?"):
            return
        try:
            _db.remove_avatar(str(_db.current_user().id))
            _db.refresh_current_profile()
        except Exception as exc:
            messagebox.showerror("Profile picture", f"Couldn't remove it:\\n{exc}")
            return
        self._rebuild_header()
        self.status_var.set("Profile picture removed.")

    def _rebuild_header(self):
        """Redraw the top bar so a changed name or picture shows straight away."""
        header = getattr(self, "_header_frame", None)
        if header is None:
            return
        for w in header.winfo_children():
            w.destroy()
        header.destroy()
        self._build_header()
        # It was packed last, so lift it back above the tab bar.
        try:
            self._header_frame.pack_configure(before=self._tab_bar_frame)
        except Exception:
            pass

    def _spin_badge(self, duration: float = 0.7):
        """One full turn of the header badge, eased in and out. A click
        while it is turning starts it again from where it is."""
        label = getattr(self, "_badge_label", None)
        if label is None or reduced_motion():
            return
        start = _time.monotonic()
        token = object()
        self._badge_spin = token

        def _step():
            if self._badge_spin is not token or not label.winfo_exists():
                return
            t = min(1.0, (_time.monotonic() - start) / duration)
            label.configure(image=self._badge.frame(360 * _ease_in_out(t)))
            if t < 1.0:
                label.after(16, _step)
            else:
                self._badge_spin = None
        _step()

    def _build_header(self):
        hdr = tk.Frame(self, bg=CCA, highlightbackground=CSP, highlightthickness=1)
        hdr.pack(fill="x")
        self._header_frame = hdr
        inner = tk.Frame(hdr, bg=CCA, padx=18, pady=8)
        inner.pack(fill="x")

        # The round badge and the name, top left. Clicking the badge gives
        # it a turn.
        self._logo_img = None
        self._badge = SpinningBadge(px(40))
        self._badge_spin = None
        if self._badge.ok:
            self._badge_label = tk.Label(inner, image=self._badge.frame(0),
                                         bg=CCA, bd=0, cursor="hand2")
            self._badge_label.pack(side="left")
            self._badge_label.bind("<Button-1>", lambda _e: self._spin_badge())
        name = tk.Frame(inner, bg=CCA)
        name.pack(side="left", padx=(px(8), 0))
        tk.Label(name, text="Total", bg=CCA, fg=CA, padx=0,
                 font=(FAM, 15, "bold")).pack(side="left")
        tk.Label(name, text="Air Filtration", bg=CCA, fg=CGR, padx=0,
                 font=(FAM, 15, "bold")).pack(side="left", padx=(px(5), 0))

        # Divider + subtitle
        tk.Frame(inner, bg=CSP, width=1, height=32).pack(side="left", padx=16)
        tk.Label(inner, text="Filter Order Entry\nWorksheet Generator",
                 bg=CCA, fg=CMU, font=(FAM, 9), justify="left",
                 anchor="w").pack(side="left")

        # Right: the account, which is also the way into the admin screens.
        if _db.is_ready() and _db.current_user():
            role = _db.current_role()
            name = _db.current_full_name() or _db.current_username()

            prof = tk.Frame(inner, bg=CCA, cursor="hand2", padx=px(6))
            prof.pack(side="right")
            av = self._avatar(prof, _initials(name), size=36,
                              url=_db.current_avatar_url())
            av.pack(side="right", padx=(px(10), 0))
            tcol = tk.Frame(prof, bg=CCA)
            tcol.pack(side="right")
            tk.Label(tcol, text=role.upper(), bg=CCA, fg=CGR,
                     font=(FAM, 8, "bold"), anchor="e").pack(anchor="e")
            namerow = tk.Frame(tcol, bg=CCA)
            namerow.pack(anchor="e")
            tk.Label(namerow, text=name, bg=CCA, fg=CTX,
                     font=(FAM, 10, "bold"), anchor="e").pack(side="left")
            tk.Label(namerow, text="  ▾", bg=CCA, fg=CMU,
                     font=(FAM, 9, "bold")).pack(side="left")
            self._profile_anchor = prof
            for w in (prof, tcol, av, namerow):
                w.bind("<Button-1>", lambda _e: self._account_menu())
                for child in w.winfo_children():
                    child.bind("<Button-1>", lambda _e: self._account_menu())

            # The bell, immediately left of the profile. Packed after it and
            # to the right, which is what puts it next to the picture rather
            # than out beyond the shortcuts link.
            self._bell = NotificationBell(inner, command=self._open_notifications)
            self._bell.pack(side="right", padx=(px(4), px(8)))
            self.master.after(1500, self._poll_notifications)

        # A shortcut nobody knows about saves nobody any time, so there is a
        # way in that doesn't require already knowing the shortcut.
        kb = tk.Label(inner, text="⌨  Shortcuts", bg=CCA, fg=CMU,
                      font=F_SM, cursor="hand2", padx=px(10))
        kb.pack(side="right", padx=(0, px(6)))
        kb.bind("<Button-1>", lambda _e: self._show_shortcuts())
        kb.bind("<Enter>", lambda _e: kb.config(fg=CA))
        kb.bind("<Leave>", lambda _e: kb.config(fg=CMU))
        _Tooltip(kb, "Keyboard shortcuts  (F1)")

    # ── Tab bar ───────────────────────────────────────────────────────────

    def _build_tab_bar(self):
        bar = tk.Frame(self, bg=CCA, highlightbackground=CSP, highlightthickness=1)
        bar.pack(fill="x")
        self._tab_bar_frame = bar

        self._tab_bar_inner = tk.Frame(bar, bg=CCA, padx=8)
        self._tab_bar_inner.pack(fill="x")

        tabs = [(k, self._TAB_LABELS[k]) for k in self._TAB_ORDER]
        self._tab_underlines = {}
        for key, label_text in tabs:
            cell = tk.Frame(self._tab_bar_inner, bg=CCA)
            cell.pack(side="left")
            btn = tk.Label(cell, text=label_text, bg=CCA, fg=CMU,
                           font=(FAM, 9, "bold"), padx=14, pady=11, cursor="hand2")
            btn.pack()
            btn.bind("<Button-1>", lambda e, k=key: self._show_tab(k))
            btn.bind("<Enter>",    lambda e, k=key: self._tab_hover(k, True))
            btn.bind("<Leave>",    lambda e, k=key: self._tab_hover(k, False))
            ul = tk.Frame(cell, bg=CCA, height=2)
            ul.pack(fill="x")
            self._tab_buttons[key]    = btn
            self._tab_underlines[key] = ul

    def _tab_hover(self, key: str, entering: bool):
        if getattr(self, "_active_tab", None) == key:
            return
        self._tab_buttons[key].config(fg=CTX if entering else CMU)

    # The tabs, left to right. One list: the bar is built from it and Ctrl+1
    # to Ctrl+0 are numbered off it, so the shortcut can never point at a
    # different tab from the one under that position on screen.
    _TAB_LABELS = {
        "dashboard":   "▦  Dashboard",
        "new_order":   "＋  New Order",
        "prev_orders": "▤  Previous Orders",
        "delivery":    "🚚  Delivery",
        "quotes":      "💲  Quotes",
        "customers":   "👥  Customers",
        "stock":        "📦  Stock",
        "supplies":    "🧰  Order Supplies",
        "audit_log":   "☰  Audit Log",
    }
    # On the bar, left to right, and numbered Ctrl+1..n off the same list.
    _TAB_ORDER = list(_TAB_LABELS)
    # Reachable, but not on the bar — they live under the account menu.
    _ADMIN_TABS = ("products", "settings")

    # ── Keyboard ──────────────────────────────────────────────────────────
    # An order-entry app is used all day by people who know where everything
    # is. Reaching for the mouse to change tab, start an order or find a
    # customer is the slowest part of the job.
    #
    # Ctrl+letter is safe to bind application-wide because it is never
    # someone typing. The Delete key is not, so it is bound to the tables
    # themselves rather than globally - otherwise it would eat a line while
    # someone was editing a field.

    # Written from the tab list rather than by hand: Settings and Products
    # moving off the bar shortened it, and a help screen promising a key that
    # does nothing is worse than no help screen.
    _TAB_KEYS = ("Ctrl+1 … Ctrl+9, Ctrl+0" if len(_TAB_ORDER) >= 10
                 else f"Ctrl+1 … Ctrl+{len(_TAB_ORDER)}")

    SHORTCUTS = [
        (_TAB_KEYS, "Jump straight to a tab, left to right"),
        ("Ctrl+N",          "Start a new order"),
        ("Ctrl+F",          "Jump to the search box on this tab"),
        ("Ctrl+S",          "Do the main thing on this tab "
                            "(generate the order, save the quote)"),
        ("Ctrl+P",          "Print — the selected order, or the delivery run"),
        ("F5",              "Reload what's on screen"),
        ("F1",              "This list"),
        ("Enter",           "Open the selected row"),
        ("Delete",          "Remove the selected line (New Order and Quotes)"),
        ("Esc",             "Close a dialog"),
    ]

    def _bind_shortcuts(self):
        root = self.master
        for i, key in enumerate(self._TAB_ORDER):
            # Ctrl+1..9 then Ctrl+0 for the tenth, the way browsers do it.
            digit = (i + 1) % 10
            root.bind_all(f"<Control-Key-{digit}>",
                          lambda _e, k=key: self._shortcut(lambda: self._show_tab(k)))
        root.bind_all("<Control-n>", lambda _e: self._shortcut(self._new_order))
        root.bind_all("<Control-N>", lambda _e: self._shortcut(self._new_order))
        root.bind_all("<Control-f>", lambda _e: self._shortcut(self._focus_search))
        root.bind_all("<Control-F>", lambda _e: self._shortcut(self._focus_search))
        root.bind_all("<Control-s>", lambda _e: self._shortcut(self._primary_action))
        root.bind_all("<Control-S>", lambda _e: self._shortcut(self._primary_action))
        root.bind_all("<Control-p>", lambda _e: self._shortcut(self._print_action))
        root.bind_all("<Control-P>", lambda _e: self._shortcut(self._print_action))
        root.bind_all("<F5>", lambda _e: self._shortcut(self._reload_active_tab))
        root.bind_all("<F1>", lambda _e: self._shortcut(self._show_shortcuts))

    def _shortcut(self, action):
        """Run a shortcut, unless a dialog is open.

        bind_all reaches every window in the program, dialogs included, so
        without this Ctrl+N inside the line-item dialog would start a new
        order behind it.
        """
        try:
            if self.master.grab_current() is not None:
                return "break"
        except Exception:
            pass
        try:
            action()
        except Exception as exc:
            self.status_var.set(f"That didn't work: {exc}")
        return "break"

    # Which box Ctrl+F should land in, per tab.
    _SEARCH_FIELDS = {
        "prev_orders": "search_var",
        "products":    "product_search_var",
        "customers":   "_cust_search_var",
        "stock":       "_stock_search_var",
    }

    def _focus_search(self):
        """Put the cursor in this tab's search box, and select what's there
        so typing replaces the last search instead of appending to it."""
        name = self._SEARCH_FIELDS.get(self._active_tab)
        widget = None
        if name:
            var = getattr(self, name, None)
            widget = self._entry_for_var(var) if var is not None else None
        if widget is None:
            self.status_var.set("Nothing to search on this tab.")
            return
        widget.focus_set()
        try:
            widget.select_range(0, "end")
            widget.icursor("end")
        except Exception:
            pass

    def _entry_for_var(self, var):
        """Find the Entry showing a given variable, wherever it was built."""
        target = str(var)
        stack = [self]
        while stack:
            w = stack.pop()
            try:
                if isinstance(w, tk.Entry) and str(w.cget("textvariable")) == target:
                    return w
                stack.extend(w.winfo_children())
            except Exception:
                continue
        return None

    def _primary_action(self):
        """Ctrl+S does the main thing on whichever tab is open."""
        tab = self._active_tab
        if tab == "new_order":
            self._generate()
        elif tab == "quotes":
            self._save_quote()
        elif tab == "stock":
            self._adjust_stock_dialog()
        else:
            self.status_var.set(
                "Ctrl+S generates an order on New Order and saves on Quotes.")

    def _print_action(self):
        tab = self._active_tab
        if tab == "delivery":
            self._print_run_sheet()
        elif tab == "prev_orders":
            self._print_prev_order()
        elif tab == "new_order":
            self._generate()
        else:
            self.status_var.set("Nothing to print on this tab.")

    def _reload_active_tab(self):
        """F5: fetch this tab again, ignoring how recently it was loaded."""
        self._tab_loaded.pop(self._active_tab, None)
        self._maybe_refresh(self._active_tab)
        self.status_var.set("Reloaded.")

    def _show_shortcuts(self):
        """A shortcut nobody knows about saves nobody any time."""
        dlg = tk.Toplevel(self.master)
        dlg.title("Keyboard Shortcuts")
        dlg.configure(bg=CBG, padx=px(22), pady=px(18))
        dlg.transient(self.master)
        dlg.resizable(False, False)
        tk.Label(dlg, text="Keyboard Shortcuts", bg=CBG, fg=CA,
                 font=F_SEC).grid(row=0, column=0, columnspan=2, sticky="w",
                                  pady=(0, px(10)))
        for r, (keys, what) in enumerate(self.SHORTCUTS, start=1):
            tk.Label(dlg, text=keys, bg=CBG, fg=CTX, font=F_BOLD,
                     anchor="w").grid(row=r, column=0, sticky="w",
                                      padx=(0, px(18)), pady=px(3))
            tk.Label(dlg, text=what, bg=CBG, fg=CMU, font=F_BODY,
                     anchor="w").grid(row=r, column=1, sticky="w", pady=px(3))
        flat_btn(dlg, "Close", dlg.destroy, bg=CA, pady=px(6)).grid(
            row=len(self.SHORTCUTS) + 1, column=0, columnspan=2,
            sticky="e", pady=(px(14), 0))
        dlg.bind("<Escape>", lambda _e: dlg.destroy())
        dlg.grab_set()

    # Where the cursor should land when a tab is opened, so the common job on
    # each screen can be started by typing rather than clicking first.
    _TAB_FOCUS = {
        "new_order":   "_focus_new_order",
        "prev_orders": "_focus_search",
        "products":    "_focus_search",
        "customers":   "_focus_search",
        "stock":       "_focus_search",
    }

    def _focus_new_order(self):
        entry = self._entry_for_var(self.hvars.get("Customer Name"))
        if entry is not None and not str(self.hvars["Customer Name"].get()).strip():
            entry.focus_set()

    def _focus_for_tab(self, key: str):
        name = self._TAB_FOCUS.get(key)
        if not name:
            return
        try:
            getattr(self, name)()
        except Exception:
            pass          # a tab that hasn't finished building yet

    def _show_tab(self, key: str):
        self._ensure_tab_built(key)   # lazily build the tab if not constructed yet
        self._active_tab = key
        for k, btn in self._tab_buttons.items():
            active = (k == key)
            btn.config(fg=CA if active else CMU)
            self._tab_underlines[k].config(bg=CA if active else CCA)

        self._tab_frames[key].tkraise()
        self._maybe_refresh(key)
        # After the tab is raised, so the widget being focused is visible.
        self.master.after_idle(lambda: self._focus_for_tab(key))

    # Seconds a tab's data stays "fresh" — bouncing between tabs within this
    # window skips the re-fetch + treeview rebuild, so switching is instant.
    _TAB_TTL = 60
    # A few tabs hold things that barely move between visits. Re-reading the
    # whole price list because someone looked at Products two minutes ago is
    # a wait for no new information.
    _TAB_TTLS = {"products": 900, "customers": 300, "audit_log": 120}

    def _maybe_refresh(self, key: str):
        """Load a tab's data on show, but skip if it was loaded recently.

        Manual Refresh buttons and data mutations call the _refresh_* methods
        directly (bypassing this gate), so they always run and re-stamp
        freshness. Order generation invalidates prev_orders + dashboard.
        """
        import time
        # Settings' local-storage line is cheap; always keep it current.
        if key == "settings" and hasattr(self, "_local_storage_lbl"):
            self._local_storage_lbl.set(self._local_storage_info())

        ttl = self._TAB_TTLS.get(key, self._TAB_TTL)
        if time.monotonic() - self._tab_loaded.get(key, 0.0) < ttl:
            return  # still fresh — instant switch, no network / rebuild
        self._tab_loaded[key] = time.monotonic()

        if key == "new_order":
            self._load_known_customers()
        elif key == "prev_orders":
            self._refresh_orders_list()
        elif key == "dashboard":
            self._refresh_dashboard()
        elif key == "customers":
            self._refresh_customers_list()
        elif key == "stock":
            self._refresh_stock_list()
        elif key == "supplies":
            self._refresh_supplies()
        elif key == "products":
            self._refresh_products_list()
        elif key == "delivery":
            self._refresh_delivery_run()
        elif key == "quotes":
            self._refresh_quote_prices()
        elif key == "audit_log":
            self._refresh_audit_log()
        elif key == "settings":
            self._refresh_media_list()

    # ── New Order tab ─────────────────────────────────────────────────────

    def _build_new_order_tab(self):
        frm = tk.Frame(self.content, bg=CBG)
        frm.grid(row=0, column=0, sticky="nsew")
        frm.columnconfigure(1, weight=1)
        frm.rowconfigure(0, weight=1)
        self._tab_frames["new_order"] = frm

        self._build_order_details_panel(frm)
        self._build_line_items_panel(frm)
        # Lines added before this tab existed — a restored draft, a purchase
        # order read from a photo — go into the table now that there is one.
        self._refresh_items_tree()

    def _build_order_details_panel(self, parent):
        left = tk.Frame(parent, bg=CBG, padx=14, pady=12)
        left.grid(row=0, column=0, sticky="nsew")

        # Card: Order Details
        # fill="x" gave it its natural height and left a slab of dead grey
        # underneath; expanding it puts the card where the space is.
        card_outer, card_body = card_frame(left, title="Order Details")
        card_outer.pack(fill="both", expand=True)
        card_body.columnconfigure(1, weight=1)

        self.hvars = {
            "Customer Name": tk.StringVar(),
            "Order Number":  tk.StringVar(),
            "Date Ordered":  tk.StringVar(),
            "Date Due":      tk.StringVar(),
            "Attention":     tk.StringVar(),
            "Job":           tk.StringVar(),
            "Location":      tk.StringVar(),
            "Delivery Fee":  tk.StringVar(),
        }

        # Auto-note rule: JAF or AES in customer name → add label/wrap note
        self.hvars["Customer Name"].trace_add(
            "write", lambda *_: self._check_customer_note()
        )
        # Customer autocomplete
        self._known_customers: list = []
        self._ac_popup: "tk.Toplevel | None" = None
        self.hvars["Customer Name"].trace_add(
            "write", lambda *_: self._customer_name_changed())
        self.hvars["Customer Name"].trace_add(
            "write", lambda *_: self._schedule_customer_list())

        DATE_FIELDS = {"Date Ordered", "Date Due"}
        REQUIRED    = {"Customer Name", "Order Number", "Date Ordered"}

        field_rows = [
            "Customer Name", "Order Number", "Date Ordered",
            "Date Due", "Attention", "Job", "Location", "Delivery Fee",
        ]

        # Store widget refs for validation highlighting
        self._hentries: dict = {}       # key → entry widget
        self._hfield_labels: dict = {}  # key → label widget

        for row, key in enumerate(field_rows):
            lbl = tk.Label(card_body, text=key,
                           bg=CCA, fg=CTX, font=F_BODY, anchor="w")
            lbl.grid(row=row, column=0, sticky="w", pady=4, padx=(0, 10))
            self._hfield_labels[key] = lbl

            if key in DATE_FIELDS:
                wrap = tk.Frame(card_body, bg=CCA)
                wrap.grid(row=row, column=1, sticky="we", pady=4)
                wrap.columnconfigure(0, weight=1)

                e = field_entry(wrap, textvariable=self.hvars[key])
                e.grid(row=0, column=0, sticky="we")
                self._hentries[key] = e

                var = self.hvars[key]
                cal_btn = FlatButton(
                    wrap, text="📅",
                    command=lambda v=var, b=None: None,
                    bg=CA, fg="white", relief="flat", bd=0,
                    font=(FAM, 9), padx=6, pady=2,
                    cursor="hand2",
                    activebackground=_dk(CA), activeforeground="white",
                )
                cal_btn.grid(row=0, column=1, padx=(3, 0))
                cal_btn.config(command=lambda v=var, b=cal_btn:
                               CalendarPicker(self.master, v, anchor=b))

                if key == "Date Due":
                    self.hvars[key].set("ASAP")
            elif key == "Order Number":
                # A customer who rings up without a purchase order number
                # still needs the job identified, so we can issue one.
                wrap = tk.Frame(card_body, bg=CCA)
                wrap.grid(row=row, column=1, sticky="we", pady=4)
                wrap.columnconfigure(0, weight=1)
                e = field_entry(wrap, textvariable=self.hvars[key])
                e.grid(row=0, column=0, sticky="we")
                self._hentries[key] = e
                self._taf_on_btn = FlatButton(
                    wrap, text="TAF #", command=self._use_supplied_order_number,
                    bg=CA, fg="white", relief="flat", bd=0,
                    font=(FAM, 8, "bold"), padx=7, pady=2, cursor="hand2",
                    activebackground=_dk(CA), activeforeground="white")
                self._taf_on_btn.grid(row=0, column=1, padx=(3, 0))
                _Tooltip(self._taf_on_btn,
                         "No purchase order number? Give this order one of "
                         "ours — TAF-ON-0001 and up.")
            elif key == "Location":
                # Which run the order goes on. It comes from the customer's
                # account; picking here is for the odd order that differs,
                # a pick-up say.
                e = ttk.Combobox(card_body, textvariable=self.hvars[key],
                                 state="readonly",
                                 values=list(_pn.REGION_NAMES))
                e.grid(row=row, column=1, sticky="we", pady=4)
                self._hentries[key] = e
                _Tooltip(e, "\n".join(f"{n}: {d}"
                                      for n, d in _pn.REGIONS.items()))
            elif key == "Delivery Fee":
                # The customer's delivery charge, filled in when the account
                # is picked and added to the invoice. A manager can change it
                # on an order; for anyone else it is the customer's.
                e = field_entry(card_body, textvariable=self.hvars[key])
                e.grid(row=row, column=1, sticky="we", pady=4)
                self._hentries[key] = e
                if not (_db.is_ready() and _db.can_manage_prices()):
                    e.config(state="readonly")
                _Tooltip(e, "Delivery charge ex GST, from the customer's "
                            "account. Added to the invoice. Empty = none.")
                self.hvars[key].trace_add(
                    "write", lambda *_: self.master.after_idle(
                        self._refresh_items_tree))
            else:
                e = field_entry(card_body, textvariable=self.hvars[key])
                e.grid(row=row, column=1, sticky="we", pady=4)
                self._hentries[key] = e
                if key == "Customer Name":
                    self._customer_entry = e
                    # Picking from the list asks in _pick_customer; this
                    # catches a name typed out in full. After a moment, so
                    # a click on the suggestions list is handled first.
                    e.bind("<FocusOut>", lambda _e: self.master.after(
                        200, self._customer_left), add="+")
                    e.bind("<Escape>", lambda _e: self._close_ac_popup(),
                           add="+")
                    for _k in ("Down", "Up", "Return"):
                        e.bind(f"<{_k}>", lambda _e, k=_k: self._ac_key(k),
                               add="+")

        # Clear individual field error as user types + trigger draft save
        for req_key in list(REQUIRED) + ["Date Due", "Location"]:
            self.hvars[req_key].trace_add(
                "write", lambda *_, k=req_key: self._clear_field_error(k))
        # Auto-save draft on any header field change
        for _hkey in self.hvars:
            self.hvars[_hkey].trace_add("write", lambda *_: self._schedule_draft_save())

        # Notes
        r = len(field_rows)
        tk.Label(card_body, text="Notes",
                 bg=CCA, fg=CTX, font=F_BODY,
                 anchor="nw").grid(row=r, column=0, sticky="nw",
                                   pady=(8, 4), padx=(0, 10))
        self.txt_header_notes = tk.Text(
            card_body, height=5, width=24, wrap="word",
            font=F_BODY, relief="flat", bd=0, highlightthickness=1, highlightbackground=CBR,
            bg=CCA, fg=CTX, insertbackground=CTX)
        # The card fills the column, so the fields left a hand's width of
        # blank white under them. Notes takes it — the one field here with no
        # natural length.
        self.txt_header_notes.grid(row=r, column=1, sticky="nsew", pady=(8, 4))
        card_body.rowconfigure(r, weight=1)
        self.txt_header_notes.bind("<<Modified>>",
            lambda e: (self.txt_header_notes.edit_modified(False),
                       self._schedule_draft_save()))

        # ── Validation error banner (hidden until needed) ─────────────────
        self._validation_banner = tk.Frame(left, bg="#FDECEA",
                                            highlightbackground=CRD,
                                            highlightthickness=1)
        # Not packed yet — shown by _validate_header() on failure
